import {
  TimeSeriesChart,
  type TimeSeriesChartProps,
} from "./time-series-chart";

export type AreaChartProps = TimeSeriesChartProps;

/** Compose with `<Area>`, `<Grid>`, `<XAxis>`, `<ChartTooltip>`, segments. */
export function AreaChart(props: AreaChartProps) {
  return <TimeSeriesChart {...props} />;
}

import { Group, LinearGradient, Path, vec } from "@shopify/react-native-skia";
import { type CurveFactory, curveMonotoneX } from "d3-shape";
import { useMemo } from "react";
import { collectValues, useChart, withChartPlugin } from "./chart-context";
import { DATA_TWEEN_MS } from "./motion";
import {
  areaBuilder,
  type FadeEdges,
  HighlightBand,
  lineBuilder,
  SeriesLayer,
  useDimOpacity,
  useKeyedMorph,
  useSeriesPoints,
} from "./series-paint";
import { withAlpha } from "./theme";

export interface AreaProps {
  dataKey: string;
  /** Tooltip label. Default: `dataKey`. */
  label?: string;
  /** Fill colour (gradient start). Default: theme primary / secondary. */
  fill?: string;
  /** Gradient start opacity. Default: 0.4 (matches web). */
  fillOpacity?: number;
  /** Line colour. Default: same as `fill`. */
  stroke?: string;
  /** Default: 2 (matches web). */
  strokeWidth?: number;
  /** Default: curveMonotoneX (matches web `Area`). */
  curve?: CurveFactory;
  /** Fade fill and stroke toward the left/right edges. Default: true. */
  fadeEdges?: FadeEdges;
  /** Dim the series and re-stroke a band around the scrubbed point. Default: true. */
  showHighlight?: boolean;
  /** Morph duration in ms when `data` changes. Default: 500 (web y-domain tween). */
  morphDuration?: number;
}

function AreaImpl({
  dataKey,
  fill,
  fillOpacity = 0.4,
  stroke,
  strokeWidth = 2,
  curve = curveMonotoneX,
  fadeEdges = true,
  showHighlight = true,
  morphDuration = DATA_TWEEN_MS,
}: AreaProps) {
  const { yScale, series, height, margin } = useChart();
  const seriesColor =
    series.find((s) => s.dataKey === dataKey)?.stroke ?? "#6366f1";
  const fillColor = fill ?? seriesColor;
  const strokeColor = stroke ?? fillColor;
  const baseline = yScale.range()[0] ?? height - margin.bottom;

  const points = useSeriesPoints(dataKey, baseline);
  const buildArea = useMemo(() => areaBuilder(curve), [curve]);
  const buildLine = useMemo(() => lineBuilder(curve), [curve]);
  const areaPath = useKeyedMorph(points, buildArea, morphDuration);
  const linePath = useKeyedMorph(points, buildLine, morphDuration);
  const opacity = useDimOpacity(showHighlight);

  const stroked = (
    <Path
      color={strokeColor}
      path={linePath}
      strokeCap="round"
      strokeJoin="round"
      strokeWidth={strokeWidth}
      style="stroke"
    />
  );

  return (
    <SeriesLayer fadeEdges={fadeEdges}>
      <Group opacity={opacity}>
        <Path path={areaPath}>
          <LinearGradient
            colors={[
              withAlpha(fillColor, fillOpacity),
              withAlpha(fillColor, 0),
            ]}
            end={vec(0, baseline)}
            start={vec(0, margin.top)}
          />
        </Path>
        {stroked}
      </Group>
      {showHighlight ? <HighlightBand>{stroked}</HighlightBand> : null}
    </SeriesLayer>
  );
}

export const Area = withChartPlugin(AreaImpl, {
  series: (props, index, theme) => ({
    dataKey: props.dataKey,
    label: props.label ?? props.dataKey,
    stroke:
      props.stroke ??
      props.fill ??
      (index === 0 ? theme.linePrimary : theme.lineSecondary),
    strokeWidth: props.strokeWidth ?? 2,
  }),
  yValues: (props, data) => collectValues(data, [props.dataKey]),
});

import { Group } from "@shopify/react-native-skia";
import { useChart } from "./chart-context";
import { EdgeFade, useEnterOpacity, usePlotRect } from "./fade-mask";
import { PatternFill, type PatternPreset } from "./patterns";

export interface BackgroundProps {
  /** Default: "dots" (homepage). */
  pattern?: PatternPreset;
  /** Default: theme grid. */
  color?: string;
  opacity?: number;
  scale?: number;
  strokeWidth?: number;
  /** Left/right fade, % of plot width per edge. Default: 10. */
  fadeHorizontalLength?: number;
  /** Top/bottom fade, % of plot height per edge. Default: 10. */
  fadeVerticalLength?: number;
}

/** Patterned plot backdrop that fades at the edges (web `Background`). */
export function Background({
  pattern = "dots",
  color,
  opacity = 1,
  scale = 1,
  strokeWidth = 1,
  fadeHorizontalLength = 10,
  fadeVerticalLength = 10,
}: BackgroundProps) {
  const { theme } = useChart();
  const rect = usePlotRect();
  const enter = useEnterOpacity();
  return (
    <Group opacity={enter}>
      <EdgeFade
        bottom={fadeVerticalLength}
        left={fadeHorizontalLength}
        rect={rect}
        right={fadeHorizontalLength}
        top={fadeVerticalLength}
      >
        <PatternFill
          color={color ?? theme.grid}
          opacity={opacity}
          preset={pattern}
          rect={rect}
          scale={scale}
          strokeWidth={strokeWidth}
        />
      </EdgeFade>
    </Group>
  );
}

import {
  DashPathEffect,
  Group,
  LinearGradient,
  Path,
  vec,
} from "@shopify/react-native-skia";
import { type CurveFactory, curveNatural } from "d3-shape";
import { useMemo } from "react";
import { collectValues, useChart, withChartPlugin } from "./chart-context";
import { DATA_TWEEN_MS } from "./motion";
import {
  areaBuilder,
  type FadeEdges,
  lineBuilder,
  SeriesLayer,
  useKeyedMorph,
  useSeriesPoints,
} from "./series-paint";
import { withAlpha } from "./theme";

export interface BandProps {
  lowerKey: string;
  upperKey: string;
  label?: string;
  /** Default: theme primary. */
  fill?: string;
  /** "gradient" fades to `gradientToOpacity` at the band's bottom. Default: "solid". */
  fillType?: "solid" | "gradient";
  /** Default: 0.15 (web). */
  fillOpacity?: number;
  gradientToOpacity?: number;
  /** Edge stroke colour. Default: `fill`. */
  stroke?: string;
  strokeOpacity?: number;
  strokeWidth?: number;
  /** e.g. `[3, 4]` (recipe). Omit for solid edges. */
  strokeDasharray?: number[];
  curve?: CurveFactory;
  /** Default: true (15%). */
  fadeEdges?: FadeEdges;
}

/** Range band between two keys with optional dashed edges (web `Band`). */
function BandImpl({
  lowerKey,
  upperKey,
  fill,
  fillType = "solid",
  fillOpacity = 0.15,
  gradientToOpacity = 0,
  stroke,
  strokeOpacity = 1,
  strokeWidth = 1,
  strokeDasharray,
  curve = curveNatural,
  fadeEdges = true,
}: BandProps) {
  const { theme } = useChart();
  const color = fill ?? theme.linePrimary;
  const edgeColor = stroke ?? color;

  const points = useSeriesPoints(lowerKey, upperKey);
  const { top, bottom } = useMemo(() => {
    const ys = points.points.flatMap((p) => [p.y, p.y0 ?? p.y]);
    return { top: Math.min(...ys), bottom: Math.max(...ys) };
  }, [points]);
  const buildArea = useMemo(() => areaBuilder(curve), [curve]);
  const buildLower = useMemo(() => lineBuilder(curve, "y"), [curve]);
  const buildUpper = useMemo(() => lineBuilder(curve, "y0"), [curve]);
  const area = useKeyedMorph(points, buildArea, DATA_TWEEN_MS);
  const lower = useKeyedMorph(points, buildLower, DATA_TWEEN_MS);
  const upper = useKeyedMorph(points, buildUpper, DATA_TWEEN_MS);
  const dash = strokeDasharray ? (
    <DashPathEffect intervals={strokeDasharray} />
  ) : null;

  return (
    <SeriesLayer fadeEdges={fadeEdges}>
      {fillType === "gradient" ? (
        <Path path={area}>
          <LinearGradient
            colors={[
              withAlpha(color, fillOpacity),
              withAlpha(color, gradientToOpacity),
            ]}
            end={vec(0, Number.isFinite(bottom) ? bottom : 0)}
            start={vec(0, Number.isFinite(top) ? top : 0)}
          />
        </Path>
      ) : (
        <Path color={withAlpha(color, fillOpacity)} path={area} />
      )}
      <Group opacity={strokeOpacity}>
        {[lower, upper].map((p, i) => (
          <Path
            color={edgeColor}
            key={i}
            path={p}
            strokeCap="round"
            strokeWidth={strokeWidth}
            style="stroke"
          >
            {dash}
          </Path>
        ))}
      </Group>
    </SeriesLayer>
  );
}

export const Band = withChartPlugin(BandImpl, {
  yValues: (props, data) =>
    collectValues(data, [props.lowerKey, props.upperKey]),
});

import type { SkFont } from "@shopify/react-native-skia";
import type { ScaleLinear, ScaleTime } from "d3-scale";
import { createContext, type ReactNode, useContext } from "react";
import type { SharedValue } from "react-native-reanimated";
import type { ChartSprings, ChartTheme } from "./theme";

export interface Margin {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export interface ChartSeries {
  dataKey: string;
  label: string;
  stroke: string;
  strokeWidth: number;
  /** Colour tooltip dot/row by the value's sign (profit / loss). */
  signColors?: { positive: string; negative: string };
}

/**
 * How a chart child feeds the shell: tooltip series and the values the
 * scales must include. Attached to components with `withChartPlugin`.
 */
export interface ChartPlugin<P = Record<string, unknown>> {
  series?: (props: P, index: number, theme: ChartTheme) => ChartSeries | null;
  yValues?: (props: P, data: Record<string, unknown>[]) => number[];
  xValues?: (props: P, data: Record<string, unknown>[]) => Date[];
}

export function withChartPlugin<P>(
  component: (props: P) => ReactNode,
  plugin: ChartPlugin<P>
): ((props: P) => ReactNode) & { chartPlugin: ChartPlugin<P> } {
  return Object.assign(component, { chartPlugin: plugin });
}

export function getChartPlugin(type: unknown): ChartPlugin | undefined {
  return (type as { chartPlugin?: ChartPlugin } | null)?.chartPlugin;
}

export interface ChartFonts {
  axis: SkFont;
  tooltip: SkFont;
  tooltipStrong: SkFont;
  ticker: SkFont;
  badge: SkFont;
}

export interface ChartContextValue {
  data: Record<string, unknown>[];
  xDataKey: string;
  width: number;
  height: number;
  margin: Margin;
  xScale: ScaleTime<number, number>;
  yScale: ScaleLinear<number, number>;
  series: ChartSeries[];
  /** Pixel x of each datum, in data order. */
  xs: number[];
  theme: ChartTheme;
  fonts: ChartFonts;
  springs: ChartSprings;
  animationDuration: number;
  reducedMotion: boolean;
  /** 0 → 1 left-to-right reveal on mount. */
  revealProgress: SharedValue<number>;

  /** Index under the finger (last one, after release). */
  activeIndex: SharedValue<number>;
  /** Crosshair x in px, springs between snapped indices. */
  crosshairX: SharedValue<number>;
  /** 0 → 1 tooltip visibility. */
  tooltipOpacity: SharedValue<number>;
  /** Floating panel x in px (its own, softer spring). */
  boxX: SharedValue<number>;
  /** Measured tooltip panel width, written by ChartTooltip. */
  boxWidth: SharedValue<number>;
  /** Current date ticker pill width, written by DateTicker. */
  tickerWidth: SharedValue<number>;
  /** Hover-highlight band, in px. */
  highlightX: SharedValue<number>;
  highlightWidth: SharedValue<number>;

  /** Two-finger segment selection, in px / data index. */
  selectionStartX: SharedValue<number>;
  selectionEndX: SharedValue<number>;
  selectionStartIndex: SharedValue<number>;
  selectionEndIndex: SharedValue<number>;
  /** 0 → 1 selection visibility. */
  selectionOpacity: SharedValue<number>;

  /** Panel fade (web: 100ms). */
  panelOpacity: SharedValue<number>;
  /** 0 → 1 panel entrance spring (scale 0.85 → 1, x ±20 → 0). */
  panelEntrance: SharedValue<number>;
  /** 1 when the panel sits left of the crosshair. */
  panelFlipped: SharedValue<number>;
  /** 0 → 1 dot/halo grow-in spring. */
  dotEntrance: SharedValue<number>;
  /** Series dim + highlight band visibility (web: 0.4s easeInOut). */
  highlightOpacity: SharedValue<number>;
}

export const ChartContext = createContext<ChartContextValue | null>(null);

export function useChart(): ChartContextValue {
  const ctx = useContext(ChartContext);
  if (!ctx) {
    throw new Error(
      "Chart components must be rendered inside <LineChart> or <AreaChart>."
    );
  }
  return ctx;
}

export function getDate(datum: Record<string, unknown>, key: string): Date {
  const value = datum[key];
  return value instanceof Date ? value : new Date(value as string | number);
}

export function getNumber(datum: Record<string, unknown>, key: string): number {
  const value = Number(datum[key]);
  return Number.isFinite(value) ? value : 0;
}

/** The value, or null when missing (e.g. actuals on forecast rows). */
export function getValue(
  datum: Record<string, unknown>,
  key: string
): number | null {
  const raw = datum[key];
  if (raw === null || raw === undefined || raw === "") {
    return null;
  }
  const value = Number(raw);
  return Number.isFinite(value) ? value : null;
}

/** Finite values of `keys` across `data`. */
export function collectValues(
  data: Record<string, unknown>[],
  keys: string[]
): number[] {
  const out: number[] = [];
  for (const d of data) {
    for (const key of keys) {
      const v = getValue(d, key);
      if (v !== null) {
        out.push(v);
      }
    }
  }
  return out;
}

export function nearestIndex(xs: number[], x: number): number {
  "worklet";
  const last = xs.length - 1;
  if (last <= 0 || x <= xs[0]) {
    return 0;
  }
  if (x >= xs[last]) {
    return last;
  }
  let lo = 0;
  let hi = last;
  while (hi - lo > 1) {
    const mid = Math.floor((lo + hi) / 2);
    if (xs[mid] < x) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  return x - xs[lo] < xs[hi] - x ? lo : hi;
}

/**
 * y at pixel `x`, linear between neighbouring defined points; NaN where the
 * series has no value (so dots can hide on forecast rows).
 */
export function sampleY(xs: number[], ys: number[], x: number): number {
  "worklet";
  const n = xs.length;
  if (n === 0) {
    return Number.NaN;
  }
  const i = nearestIndex(xs, x);
  const yi = ys[i] ?? Number.NaN;
  if (!Number.isFinite(yi)) {
    return Number.NaN;
  }
  const j = x >= (xs[i] ?? 0) ? i + 1 : i - 1;
  const yj = ys[j];
  const xi = xs[i] ?? 0;
  const xj = xs[j];
  if (
    yj === undefined ||
    xj === undefined ||
    !Number.isFinite(yj) ||
    xj === xi
  ) {
    return yi;
  }
  const t = (x - xi) / (xj - xi);
  return yi + (yj - yi) * t;
}

import {
  Circle,
  DashPathEffect,
  Group,
  Line,
  LinearGradient,
  Rect,
  RoundedRect,
  rect,
  rrect,
  Shadow,
  type SkFont,
  Text,
  vec,
} from "@shopify/react-native-skia";
import { useEffect, useMemo } from "react";
import {
  type SharedValue,
  useAnimatedReaction,
  useDerivedValue,
  useSharedValue,
  withSpring,
} from "react-native-reanimated";
import {
  type ChartSeries,
  getDate,
  getValue,
  sampleY,
  useChart,
} from "./chart-context";
import { DateTicker } from "./date-ticker";
import { type ChartMarker, markerIndex } from "./markers";
import {
  DOT_HALO_OPACITY,
  DOT_HALO_SCALE,
  DOT_SIZE,
  PANEL_ENTRANCE_SCALE,
  PANEL_ENTRANCE_X,
} from "./motion";
import { withAlpha } from "./theme";

export type IndicatorFadeEdges = "both" | "top" | "bottom" | "none";

export interface ChartTooltipProps {
  formatLabel?: (date: Date) => string;
  formatValue?: (value: number) => string;
  showCrosshair?: boolean;
  showDots?: boolean;
  /** Rolling month/day pill on the x-axis. Default: true. */
  showDatePill?: boolean;
  /**
   * Pill label. Split on the first space into two rolling stacks
   * ("Jan 27" → "Jan" + "27"); one word ("Wednesday") rolls as one.
   */
  datePillFormat?: (date: Date) => string;
  /** Floating panel with the header and rows. Default: true. */
  showPanel?: boolean;
  /** Crosshair dash pattern, e.g. `[4, 4]`. Omit for the gradient line. */
  indicatorDasharray?: [number, number];
  /** Vertical crosshair fade (ignored when dashed). Default: "both". */
  indicatorFadeEdges?: IndicatorFadeEdges;
  /** Crosshair colour. Default: theme crosshair. */
  indicatorColor?: string;
  /** Colour the crosshair like this series' dot (e.g. profit / loss sign). */
  indicatorColorFrom?: string;
  /** Add marker rows (title + description) on marker days. Max 2, then "+N more". */
  markers?: ChartMarker[];
}

// Panel metrics (web TooltipContent: px-3.5, header py-2.5, rows gap-2).
const PAD_X = 12;
const HEADER_H = 32;
const BODY_PAD_Y = 10;
const ROW_H = 18;
const ROW_GAP = 6;
const ROW_DOT = 8;
const LABEL_GAP = 8;
const VALUE_GAP = 24;
const MIN_WIDTH = 150;
const RADIUS = 12;
const MARKER_SECTION_GAP = 8;
const MARKER_ROW_H = 36;
const MARKER_MORE_H = 16;
const MAX_MARKER_ROWS = 2;
/** Web PANEL_SIZE_SPRING: critically damped, hugs new content. */
const PANEL_SIZE_SPRING = { stiffness: 500, damping: 45, mass: 1 };
/** Indicator fade zone, % of its height (web default 10). */
const INDICATOR_FADE = 0.1;

const defaultLabel = (date: Date) =>
  date.toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
  });
const defaultValue = (value: number) => value.toLocaleString("en-US");

/**
 * Crosshair, series dots, date ticker and floating panel, all drawn in Skia
 * and driven by springs on the UI thread, so scrubbing never re-renders React.
 */
export function ChartTooltip({
  formatLabel = defaultLabel,
  formatValue = defaultValue,
  showCrosshair = true,
  showDots = true,
  showDatePill = true,
  datePillFormat,
  showPanel = true,
  indicatorDasharray,
  indicatorFadeEdges = "both",
  indicatorColor,
  indicatorColorFrom,
  markers,
}: ChartTooltipProps) {
  const {
    data,
    xDataKey,
    height,
    margin,
    xs,
    yScale,
    series,
    theme,
    fonts,
    activeIndex,
    crosshairX,
    tooltipOpacity,
    boxX,
    boxWidth,
    panelOpacity,
    panelEntrance,
    panelFlipped,
    dotEntrance,
  } = useChart();

  const titles = useMemo(
    () => data.map((d) => formatLabel(getDate(d, xDataKey))),
    [data, xDataKey, formatLabel]
  );

  const rows = useMemo(
    () =>
      series.map((s) => {
        const raw = data.map((d) => getValue(d, s.dataKey));
        const values = raw.map((v) => (v === null ? "—" : formatValue(v)));
        const sign = s.signColors;
        return {
          series: s,
          values,
          valueWidths: values.map((v) => fonts.tooltipStrong.getTextWidth(v)),
          labelWidth: fonts.tooltip.getTextWidth(s.label),
          ys: raw.map((v) => (v === null ? Number.NaN : yScale(v))),
          colors: raw.map((v) => {
            if (!sign) {
              return s.stroke;
            }
            return (v ?? 0) >= 0 ? sign.positive : sign.negative;
          }),
        };
      }),
    [series, data, formatValue, fonts, yScale]
  );

  // Per data index: up to two markers, plus "+N more".
  const markerRows = useMemo(() => {
    const slots = Array.from({ length: MAX_MARKER_ROWS }, () => ({
      titles: [] as string[],
      descriptions: [] as string[],
      colors: [] as string[],
    }));
    const more: string[] = [];
    const extra: number[] = [];
    let widest = 0;
    data.forEach((d, i) => {
      const hits = (markers ?? []).filter(
        (m) => markerIndex([d], xDataKey, m.date) === 0
      );
      slots.forEach((slot, k) => {
        const m = hits[k];
        slot.titles[i] = m?.title ?? "";
        slot.descriptions[i] = m?.description ?? "";
        slot.colors[i] = m?.color ?? theme.foregroundMuted;
        if (m) {
          widest = Math.max(
            widest,
            fonts.tooltipStrong.getTextWidth(m.title),
            fonts.tooltip.getTextWidth(m.description ?? "")
          );
        }
      });
      const overflow = hits.length - MAX_MARKER_ROWS;
      more[i] = overflow > 0 ? `+${overflow} more…` : "";
      const shown = Math.min(MAX_MARKER_ROWS, hits.length);
      extra[i] =
        shown > 0
          ? MARKER_SECTION_GAP +
            shown * MARKER_ROW_H +
            (overflow > 0 ? MARKER_MORE_H : 0)
          : 0;
    });
    return { slots, more, extra, widest };
  }, [data, xDataKey, markers, fonts, theme.foregroundMuted]);

  const panelWidth = useMemo(() => {
    const titleW = Math.max(
      0,
      ...titles.map((t) => fonts.tooltipStrong.getTextWidth(t))
    );
    const rowW = Math.max(
      0,
      ...rows.map(
        (r) =>
          ROW_DOT +
          LABEL_GAP +
          r.labelWidth +
          VALUE_GAP +
          Math.max(0, ...r.valueWidths)
      )
    );
    const markerW = markerRows.widest
      ? markerRows.widest + ROW_DOT + LABEL_GAP
      : 0;
    return Math.ceil(
      Math.max(
        MIN_WIDTH,
        titleW + PAD_X * 2,
        rowW + PAD_X * 2,
        markerW + PAD_X * 2
      )
    );
  }, [titles, rows, fonts, markerRows.widest]);

  useEffect(() => {
    boxWidth.value = showPanel ? panelWidth : 0;
  }, [boxWidth, panelWidth, showPanel]);

  const bodyBottom =
    HEADER_H + BODY_PAD_Y + rows.length * ROW_H + (rows.length - 1) * ROW_GAP;
  const baseHeight = bodyBottom + BODY_PAD_Y;
  // Grows for marker rows on marker days (web panel size spring).
  const panelHeight = useSharedValue(baseHeight);
  const extra = markerRows.extra;
  useAnimatedReaction(
    () => activeIndex.value,
    (i) => {
      const target = baseHeight + (extra[i] ?? 0);
      panelHeight.value =
        panelOpacity.value === 0
          ? target
          : withSpring(target, PANEL_SIZE_SPRING);
    }
  );
  const borderHeight = useDerivedValue(() => panelHeight.value - 1);
  const panelClip = useDerivedValue(() =>
    rrect(rect(0, 0, panelWidth, panelHeight.value), RADIUS, RADIUS)
  );
  const crosshairColors = useMemo(
    () => rows.find((r) => r.series.dataKey === indicatorColorFrom)?.colors,
    [rows, indicatorColorFrom]
  );
  const top = margin.top;
  const bottom = height - margin.bottom;

  const title = useDerivedValue(() => titles[activeIndex.value] ?? "");
  // Web entrance: scale 0.85 → 1 and x ∓20 → 0 from the crosshair-side top
  // corner, on PANEL_ENTRANCE_SPRING. Origin flips with the panel.
  const panelTransform = useDerivedValue(() => {
    const e = panelEntrance.value;
    const flipped = panelFlipped.value === 1;
    const originX = flipped ? panelWidth : 0;
    const slide = (flipped ? PANEL_ENTRANCE_X : -PANEL_ENTRANCE_X) * (1 - e);
    const scale = PANEL_ENTRANCE_SCALE + (1 - PANEL_ENTRANCE_SCALE) * e;
    return [
      { translateX: boxX.value + slide + originX },
      { translateY: top },
      { scale },
      { translateX: -originX },
    ];
  });

  return (
    <>
      {showCrosshair ? (
        <Crosshair
          activeIndex={activeIndex}
          bottom={bottom}
          color={indicatorColor ?? theme.crosshair}
          colors={crosshairColors}
          crosshairX={crosshairX}
          dash={indicatorDasharray}
          fade={indicatorFadeEdges}
          opacity={tooltipOpacity}
          top={top}
        />
      ) : null}
      {showDots
        ? rows.map((r) => (
            <TooltipDot
              activeIndex={activeIndex}
              colors={r.colors}
              crosshairX={crosshairX}
              entrance={dotEntrance}
              key={r.series.dataKey}
              opacity={tooltipOpacity}
              xs={xs}
              ys={r.ys}
            />
          ))
        : null}
      {showDatePill ? <DateTicker formatLabel={datePillFormat} /> : null}
      {showPanel ? (
        <Group opacity={panelOpacity} transform={panelTransform}>
          <Group>
            <RoundedRect
              color={theme.tooltipBackground}
              height={panelHeight}
              r={RADIUS}
              width={panelWidth}
              x={0}
              y={0}
            >
              <Shadow blur={12} color="rgba(0,0,0,0.10)" dx={0} dy={4} />
            </RoundedRect>
            <RoundedRect
              color={theme.tooltipBorder}
              height={borderHeight}
              r={RADIUS - 0.5}
              strokeWidth={1}
              style="stroke"
              width={panelWidth - 1}
              x={0.5}
              y={0.5}
            />
            <Text
              color={theme.tooltipForeground}
              font={fonts.tooltipStrong}
              text={title}
              x={PAD_X}
              y={HEADER_H / 2 + 4.5}
            />
            <Rect
              color={theme.tooltipBorder}
              height={1}
              width={panelWidth}
              x={0}
              y={HEADER_H}
            />
            {rows.map((r, i) => (
              <TooltipRow
                activeIndex={activeIndex}
                colors={r.colors}
                key={r.series.dataKey}
                labelColor={theme.tooltipMuted}
                labelFont={fonts.tooltip}
                panelWidth={panelWidth}
                series={r.series}
                valueColor={theme.tooltipForeground}
                valueFont={fonts.tooltipStrong}
                values={r.values}
                valueWidths={r.valueWidths}
                y={HEADER_H + BODY_PAD_Y + i * (ROW_H + ROW_GAP)}
              />
            ))}
            {markers?.length ? (
              <Group clip={panelClip}>
                <MarkerSection
                  activeIndex={activeIndex}
                  divider={theme.tooltipBorder}
                  fonts={fonts}
                  more={markerRows.more}
                  muted={theme.tooltipMuted}
                  panelWidth={panelWidth}
                  slots={markerRows.slots}
                  strong={theme.tooltipForeground}
                  top={bodyBottom + BODY_PAD_Y}
                />
              </Group>
            ) : null}
          </Group>
        </Group>
      ) : null}
    </>
  );
}

function MarkerSection({
  slots,
  more,
  activeIndex,
  top,
  panelWidth,
  fonts,
  divider,
  strong,
  muted,
}: {
  slots: { titles: string[]; descriptions: string[]; colors: string[] }[];
  more: string[];
  activeIndex: SharedValue<number>;
  top: number;
  panelWidth: number;
  fonts: ReturnType<typeof useChart>["fonts"];
  divider: string;
  strong: string;
  muted: string;
}) {
  const visible = useDerivedValue(() =>
    slots[0]?.titles[activeIndex.value] ? 1 : 0
  );
  const moreText = useDerivedValue(() => more[activeIndex.value] ?? "");
  const moreY = useDerivedValue(() => {
    const shown = slots.filter((s) => s.titles[activeIndex.value]).length;
    return top + MARKER_SECTION_GAP + shown * MARKER_ROW_H + 11;
  });
  return (
    <Group opacity={visible}>
      <Rect
        color={divider}
        height={1}
        width={panelWidth - PAD_X * 2}
        x={PAD_X}
        y={top}
      />
      {slots.map((slot, k) => (
        <MarkerRow
          activeIndex={activeIndex}
          fonts={fonts}
          key={k}
          muted={muted}
          slot={slot}
          strong={strong}
          y={top + MARKER_SECTION_GAP + k * MARKER_ROW_H}
        />
      ))}
      <Text
        color={muted}
        font={fonts.tooltip}
        text={moreText}
        x={PAD_X}
        y={moreY}
      />
    </Group>
  );
}

function MarkerRow({
  slot,
  activeIndex,
  y,
  fonts,
  strong,
  muted,
}: {
  slot: { titles: string[]; descriptions: string[]; colors: string[] };
  activeIndex: SharedValue<number>;
  y: number;
  fonts: ReturnType<typeof useChart>["fonts"];
  strong: string;
  muted: string;
}) {
  const title = useDerivedValue(() => slot.titles[activeIndex.value] ?? "");
  const description = useDerivedValue(
    () => slot.descriptions[activeIndex.value] ?? ""
  );
  const color = useDerivedValue(() => slot.colors[activeIndex.value] ?? muted);
  const visible = useDerivedValue(() => (title.value ? 1 : 0));
  return (
    <Group opacity={visible}>
      <Circle
        color={color}
        cx={PAD_X + ROW_DOT / 2}
        cy={y + 9}
        r={ROW_DOT / 2}
      />
      <Text
        color={strong}
        font={fonts.tooltipStrong}
        text={title}
        x={PAD_X + ROW_DOT + LABEL_GAP}
        y={y + 13}
      />
      <Text
        color={muted}
        font={fonts.tooltip}
        text={description}
        x={PAD_X + ROW_DOT + LABEL_GAP}
        y={y + 30}
      />
    </Group>
  );
}

function fadeStops(fade: IndicatorFadeEdges, color: string) {
  const clear = withAlpha(color, 0);
  const f = INDICATOR_FADE;
  switch (fade) {
    case "top":
      return { colors: [clear, color, color], positions: [0, f, 1] };
    case "bottom":
      return { colors: [color, color, clear], positions: [0, 1 - f, 1] };
    case "none":
      return { colors: [color, color], positions: [0, 1] };
    default:
      return {
        colors: [clear, color, color, clear],
        positions: [0, f, 1 - f, 1],
      };
  }
}

function Crosshair({
  activeIndex,
  colors,
  crosshairX,
  opacity,
  top,
  bottom,
  color,
  dash,
  fade,
}: {
  crosshairX: SharedValue<number>;
  opacity: SharedValue<number>;
  top: number;
  bottom: number;
  color: string;
  dash?: [number, number];
  fade: IndicatorFadeEdges;
  activeIndex: SharedValue<number>;
  colors?: string[];
}) {
  const live = useDerivedValue(
    () => (colors ? colors[activeIndex.value] : undefined) ?? color
  );
  const p1 = useDerivedValue(() => ({ x: crosshairX.value, y: top }));
  const p2 = useDerivedValue(() => ({ x: crosshairX.value, y: bottom }));
  const barX = useDerivedValue(() => crosshairX.value - 0.5);

  // Per-point colour (e.g. profit / loss) draws a plain line.
  if (dash || colors) {
    return (
      <Line color={live} opacity={opacity} p1={p1} p2={p2} strokeWidth={1}>
        {dash ? <DashPathEffect intervals={dash} /> : null}
      </Line>
    );
  }

  const stops = fadeStops(fade, color);
  return (
    <Rect height={bottom - top} opacity={opacity} width={1} x={barX} y={top}>
      <LinearGradient
        colors={stops.colors}
        end={vec(0, bottom)}
        positions={stops.positions}
        start={vec(0, top)}
      />
    </Rect>
  );
}

function TooltipDot({
  xs,
  ys,
  colors,
  activeIndex,
  crosshairX,
  opacity,
  entrance,
}: {
  xs: number[];
  ys: number[];
  colors: string[];
  activeIndex: SharedValue<number>;
  crosshairX: SharedValue<number>;
  opacity: SharedValue<number>;
  entrance: SharedValue<number>;
}) {
  const halos = useMemo(
    () => colors.map((c) => withAlpha(c, DOT_HALO_OPACITY)),
    [colors]
  );
  // Rides the crosshair spring, following the line between points; hidden
  // where the series has no value.
  const cy = useDerivedValue(() => sampleY(xs, ys, crosshairX.value));
  const visible = useDerivedValue(() =>
    Number.isFinite(cy.value) ? opacity.value : 0
  );
  const safeCy = useDerivedValue(() =>
    Number.isFinite(cy.value) ? cy.value : -100
  );
  const color = useDerivedValue(() => colors[activeIndex.value] ?? "#000");
  const halo = useDerivedValue(() => halos[activeIndex.value] ?? "#0000");
  // Web tooltip-dot: dot 2.5 → 5, halo 5 → 13, both on HALO_SPRING.
  const r = useDerivedValue(() => DOT_SIZE * (0.5 + 0.5 * entrance.value));
  const haloR = useDerivedValue(
    () => DOT_SIZE + DOT_SIZE * (DOT_HALO_SCALE - 1) * entrance.value
  );
  return (
    <Group opacity={visible}>
      <Circle color={halo} cx={crosshairX} cy={safeCy} r={haloR} />
      <Circle color={color} cx={crosshairX} cy={safeCy} r={r} />
    </Group>
  );
}

function TooltipRow({
  series,
  colors,
  values,
  valueWidths,
  activeIndex,
  panelWidth,
  y,
  labelFont,
  valueFont,
  labelColor,
  valueColor,
}: {
  series: ChartSeries;
  colors: string[];
  values: string[];
  valueWidths: number[];
  activeIndex: SharedValue<number>;
  panelWidth: number;
  y: number;
  labelFont: SkFont;
  valueFont: SkFont;
  labelColor: string;
  valueColor: string;
}) {
  const value = useDerivedValue(() => values[activeIndex.value] ?? "");
  const valueX = useDerivedValue(
    () => panelWidth - PAD_X - (valueWidths[activeIndex.value] ?? 0)
  );
  const dotColor = useDerivedValue(
    () => colors[activeIndex.value] ?? series.stroke
  );
  const baseline = y + ROW_H / 2 + 4.5;
  return (
    <>
      <Circle
        color={dotColor}
        cx={PAD_X + ROW_DOT / 2}
        cy={y + ROW_H / 2}
        r={ROW_DOT / 2}
      />
      <Text
        color={labelColor}
        font={labelFont}
        text={series.label}
        x={PAD_X + ROW_DOT + LABEL_GAP}
        y={baseline}
      />
      <Text
        color={valueColor}
        font={valueFont}
        text={value}
        x={valueX}
        y={baseline}
      />
    </>
  );
}

import {
  Group,
  RoundedRect,
  rect,
  type SkFont,
  Text,
} from "@shopify/react-native-skia";
import { useEffect, useMemo } from "react";
import {
  useAnimatedReaction,
  useDerivedValue,
  useSharedValue,
  withSpring,
} from "react-native-reanimated";
import { getDate, useChart } from "./chart-context";

export interface DateTickerProps {
  /** Must produce "<month> <day>" style labels; split on the first space. */
  formatLabel?: (date: Date) => string;
}

// Web DateTicker: h-6 rows, px-4 / py-1 pill, gap-1 between stacks.
const ITEM_H = 24;
const PAD_X = 16;
const PAD_Y = 4;
const GAP = 4;
/** Measured widths are advance widths; pad so glyph edges aren't clipped. */
const WIDTH_SLACK = 2;
/** Stack clips extend this far so glyph overhang ("y", "f") isn't cut. */
const CLIP_BLEED = 2;
const PILL_H = ITEM_H + PAD_Y * 2;
/** Above this many points, roll the whole label as one stack (web: 60). */
const COMPACT_THRESHOLD = 60;

const defaultFormat = (date: Date) =>
  date.toLocaleDateString("en-US", { month: "short", day: "numeric" });

interface Stack {
  /** Unique consecutive values, e.g. ["Sep", "Oct"]. */
  values: string[];
  widths: number[];
  /** Data index → stack index. */
  indexOf: number[];
}

function toStack(parts: string[], font: SkFont): Stack {
  const values: string[] = [];
  const indexOf: number[] = [];
  for (const part of parts) {
    if (values.at(-1) !== part) {
      values.push(part);
    }
    indexOf.push(values.length - 1);
  }
  return {
    values,
    widths: values.map((v) =>
      v ? Math.ceil(font.getTextWidth(v)) + WIDTH_SLACK : 0
    ),
    indexOf,
  };
}

/**
 * The web DateTicker: a pill that rides the crosshair along the x-axis, with
 * month and day rolling vertically like NumberFlow. Every frame runs on the
 * UI thread; React only renders when data changes.
 */
export function DateTicker({ formatLabel = defaultFormat }: DateTickerProps) {
  const {
    data,
    xDataKey,
    width,
    height,
    margin,
    theme,
    fonts,
    springs,
    reducedMotion,
    activeIndex,
    crosshairX,
    tooltipOpacity,
    tickerWidth,
  } = useChart();

  const { month, day } = useMemo(() => {
    const labels = data.map((d) => formatLabel(getDate(d, xDataKey)));
    const compact = labels.length > COMPACT_THRESHOLD;
    const split = labels.map((label) => {
      if (compact) {
        return [label, ""] as const;
      }
      const space = label.indexOf(" ");
      return space < 0
        ? ([label, ""] as const)
        : ([label.slice(0, space), label.slice(space + 1)] as const);
    });
    return {
      month: toStack(
        split.map((s) => s[0]),
        fonts.ticker
      ),
      day: toStack(
        split.map((s) => s[1]),
        fonts.ticker
      ),
    };
  }, [data, xDataKey, formatLabel, fonts.ticker]);

  const monthY = useSharedValue(0);
  const dayY = useSharedValue(0);
  const monthW = useSharedValue(month.widths[0] ?? 0);
  const dayW = useSharedValue(day.widths[0] ?? 0);

  const spring = springs.ticker;

  const pillWidthFor = (m: number, d: number) => {
    "worklet";
    return PAD_X * 2 + m + (d > 0 ? GAP + d : 0);
  };

  useAnimatedReaction(
    () => activeIndex.value,
    (i) => {
      const mi = month.indexOf[i] ?? 0;
      const di = day.indexOf[i] ?? 0;
      const mw = month.widths[mi] ?? 0;
      const dw = day.widths[di] ?? 0;
      // Jump on first show so the pill doesn't roll in from the last date.
      const jump = reducedMotion || tooltipOpacity.value < 0.05;
      if (jump) {
        monthY.value = -mi * ITEM_H;
        dayY.value = -di * ITEM_H;
        monthW.value = mw;
        dayW.value = dw;
      } else {
        monthY.value = withSpring(-mi * ITEM_H, spring);
        dayY.value = withSpring(-di * ITEM_H, spring);
        monthW.value = withSpring(mw, spring);
        dayW.value = withSpring(dw, spring);
      }
      tickerWidth.value = pillWidthFor(mw, dw);
    }
  );

  // Clear the axis-label fade when the ticker unmounts.
  useEffect(
    () => () => {
      tickerWidth.value = 0;
    },
    [tickerWidth]
  );

  const pillWidth = useDerivedValue(() =>
    pillWidthFor(monthW.value, dayW.value)
  );
  const top = height - margin.bottom / 2 - PILL_H / 2;

  const pillTransform = useDerivedValue(() => {
    const w = pillWidth.value;
    const x = Math.min(Math.max(crosshairX.value - w / 2, 0), width - w);
    return [{ translateX: x }, { translateY: top }];
  });

  const monthClip = useDerivedValue(() =>
    rect(
      PAD_X - CLIP_BLEED,
      PAD_Y - CLIP_BLEED,
      monthW.value + CLIP_BLEED * 2,
      ITEM_H + CLIP_BLEED * 2
    )
  );
  const dayX = useDerivedValue(
    () => PAD_X + monthW.value + (dayW.value > 0 ? GAP : 0)
  );
  const dayClip = useDerivedValue(() =>
    rect(
      dayX.value - CLIP_BLEED,
      PAD_Y - CLIP_BLEED,
      dayW.value + CLIP_BLEED * 2,
      ITEM_H + CLIP_BLEED * 2
    )
  );
  const monthTransform = useDerivedValue(() => [
    { translateX: PAD_X + monthW.value / 2 },
    { translateY: PAD_Y + monthY.value },
  ]);
  const dayTransform = useDerivedValue(() => [
    { translateX: dayX.value + dayW.value / 2 },
    { translateY: PAD_Y + dayY.value },
  ]);

  return (
    <Group opacity={tooltipOpacity} transform={pillTransform}>
      <RoundedRect
        color={theme.tickerBackground}
        height={PILL_H}
        r={PILL_H / 2}
        width={pillWidth}
        x={0}
        y={0}
      />
      <Group clip={monthClip}>
        <Group transform={monthTransform}>
          <StackItems
            color={theme.tickerForeground}
            font={fonts.ticker}
            stack={month}
          />
        </Group>
      </Group>
      <Group clip={dayClip}>
        <Group transform={dayTransform}>
          <StackItems
            color={theme.tickerForeground}
            font={fonts.ticker}
            stack={day}
          />
        </Group>
      </Group>
    </Group>
  );
}

function StackItems({
  stack,
  font,
  color,
}: {
  stack: Stack;
  font: SkFont;
  color: string;
}) {
  const baseline = ITEM_H / 2 + font.getSize() * 0.36;
  return (
    <>
      {stack.values.map((value, k) =>
        value ? (
          <Text
            color={color}
            font={font}
            key={`${value}-${k}`}
            text={value}
            x={-(stack.widths[k] ?? 0) / 2}
            y={k * ITEM_H + baseline}
          />
        ) : null
      )}
    </>
  );
}

import {
  Group,
  LinearGradient,
  Mask,
  Rect,
  vec,
} from "@shopify/react-native-skia";
import { type ReactNode, useEffect } from "react";
import { useSharedValue, withTiming } from "react-native-reanimated";
import { useChart } from "./chart-context";
import { EASE_OUT, ENTER_FADE_MS } from "./motion";
import type { PatternRect } from "./patterns";

const CLEAR = "rgba(0,0,0,0)";
const SOLID = "#000";

function stops(start: number, end: number) {
  const a = Math.min(45, Math.max(0, start)) / 100;
  const b = Math.min(45, Math.max(0, end)) / 100;
  return {
    colors: [a > 0 ? CLEAR : SOLID, SOLID, SOLID, b > 0 ? CLEAR : SOLID],
    positions: [0, a, 1 - b, 1],
  };
}

export interface EdgeFadeProps {
  rect: PatternRect;
  /** Fade zones as % of the rect, per edge (0–45). */
  left?: number;
  right?: number;
  top?: number;
  bottom?: number;
  children: ReactNode;
}

/** Alpha-mask children so they fade out toward the chosen edges. */
export function EdgeFade({
  rect,
  left = 0,
  right = 0,
  top = 0,
  bottom = 0,
  children,
}: EdgeFadeProps) {
  if (left + right + top + bottom === 0) {
    return <>{children}</>;
  }
  const { x, y, width, height } = rect;
  const h = stops(left, right);
  const v = stops(top, bottom);
  return (
    <Mask
      mask={
        <Group>
          <Rect height={height} width={width} x={x} y={y}>
            <LinearGradient
              colors={h.colors}
              end={vec(x + width, 0)}
              positions={h.positions}
              start={vec(x, 0)}
            />
          </Rect>
          <Rect blendMode="dstIn" height={height} width={width} x={x} y={y}>
            <LinearGradient
              colors={v.colors}
              end={vec(0, y + height)}
              positions={v.positions}
              start={vec(0, y)}
            />
          </Rect>
        </Group>
      }
    >
      {children}
    </Mask>
  );
}

/** The plot area (inside margins). */
export function usePlotRect(): PatternRect {
  const { width, height, margin } = useChart();
  return {
    x: margin.left,
    y: margin.top,
    width: Math.max(0, width - margin.left - margin.right),
    height: Math.max(0, height - margin.top - margin.bottom),
  };
}

/** 0 → 1 over 420ms ease-out on mount, like web decorative layers. */
export function useEnterOpacity(duration = ENTER_FADE_MS) {
  const { reducedMotion } = useChart();
  const opacity = useSharedValue(reducedMotion ? 1 : 0);
  useEffect(() => {
    opacity.value = withTiming(1, {
      duration: reducedMotion ? 0 : duration,
      easing: EASE_OUT,
    });
  }, [opacity, reducedMotion, duration]);
  return opacity;
}

import {
  DashPathEffect,
  LinearGradient,
  Path,
  Skia,
  vec,
} from "@shopify/react-native-skia";
import { useMemo } from "react";
import { useChart } from "./chart-context";

export interface GridProps {
  horizontal?: boolean;
  vertical?: boolean;
  numTicksRows?: number;
  numTicksColumns?: number;
  stroke?: string;
  strokeWidth?: number;
  /** Default: [4, 4] (matches web "4,4"). Pass `null` for solid lines. */
  strokeDasharray?: [number, number] | null;
  /** Fade horizontal lines out at the left and right edges. Default: true. */
  fadeHorizontal?: boolean;
  /** Emphasised rows, e.g. `[0]` for a profit/loss zero line. */
  highlightRowValues?: number[];
  /** Default: theme foreground. */
  highlightRowStroke?: string;
  /** Default: 0.35 (web P&L examples). */
  highlightRowStrokeOpacity?: number;
  highlightRowStrokeWidth?: number;
  /** Default: [4, 4]. `null` for solid. */
  highlightRowStrokeDasharray?: [number, number] | null;
}

export function Grid({
  horizontal = true,
  vertical = false,
  numTicksRows = 5,
  numTicksColumns = 10,
  stroke,
  strokeWidth = 1,
  strokeDasharray = [4, 4],
  fadeHorizontal = true,
  highlightRowValues,
  highlightRowStroke,
  highlightRowStrokeOpacity = 0.35,
  highlightRowStrokeWidth = 1,
  highlightRowStrokeDasharray = [4, 4],
}: GridProps) {
  const { width, height, margin, xScale, yScale, theme } = useChart();
  const color = stroke ?? theme.grid;
  const left = margin.left;
  const right = width - margin.right;

  // One path for every row → one draw call.
  const rows = useMemo(() => {
    const p = Skia.PathBuilder.Make();
    if (horizontal) {
      for (const tick of yScale.ticks(numTicksRows)) {
        const y = Math.round(yScale(tick)) + 0.5;
        p.moveTo(left, y);
        p.lineTo(right, y);
      }
    }
    return p.build();
  }, [horizontal, yScale, numTicksRows, left, right]);

  const columns = useMemo(() => {
    const p = Skia.PathBuilder.Make();
    if (vertical) {
      for (const tick of xScale.ticks(numTicksColumns)) {
        const x = Math.round(xScale(tick)) + 0.5;
        p.moveTo(x, margin.top);
        p.lineTo(x, height - margin.bottom);
      }
    }
    return p.build();
  }, [vertical, xScale, numTicksColumns, margin, height]);

  const highlightRows = useMemo(() => {
    const p = Skia.PathBuilder.Make();
    for (const value of highlightRowValues ?? []) {
      const y = Math.round(yScale(value)) + 0.5;
      p.moveTo(left, y);
      p.lineTo(right, y);
    }
    return p.build();
  }, [highlightRowValues, yScale, left, right]);
  const highlightColor = highlightRowStroke ?? theme.foreground;

  const dash = strokeDasharray ? (
    <DashPathEffect intervals={strokeDasharray} />
  ) : null;

  return (
    <>
      <Path color={color} path={rows} strokeWidth={strokeWidth} style="stroke">
        {dash}
        {fadeHorizontal ? (
          <LinearGradient
            colors={["transparent", color, color, "transparent"]}
            end={vec(right, 0)}
            positions={[0, 0.1, 0.9, 1]}
            start={vec(left, 0)}
          />
        ) : null}
      </Path>
      {vertical ? (
        <Path
          color={color}
          path={columns}
          strokeWidth={strokeWidth}
          style="stroke"
        >
          {dash}
        </Path>
      ) : null}
      {highlightRowValues?.length ? (
        <Path
          color={highlightColor}
          opacity={highlightRowStrokeOpacity}
          path={highlightRows}
          strokeWidth={highlightRowStrokeWidth}
          style="stroke"
        >
          {highlightRowStrokeDasharray ? (
            <DashPathEffect intervals={highlightRowStrokeDasharray} />
          ) : null}
          {fadeHorizontal ? (
            <LinearGradient
              colors={[
                "transparent",
                highlightColor,
                highlightColor,
                "transparent",
              ]}
              end={vec(right, 0)}
              positions={[0, 0.1, 0.9, 1]}
              start={vec(left, 0)}
            />
          ) : null}
        </Path>
      ) : null}
    </>
  );
}

