/**
 * Two-finger segment selection, the native take on the web's press-and-drag
 * `SegmentBackground` / `SegmentLineFrom` / `SegmentLineTo`. Selection stays
 * until the next touch.
 */

/** Hidden below this width, like web (5px). */
const MIN_SELECTION_PX = 5;

function useSelectionOpacity() {
  const { selectionOpacity, selectionStartX, selectionEndX } = useChart();
  return useDerivedValue(() =>
    Math.abs(selectionEndX.value - selectionStartX.value) > MIN_SELECTION_PX
      ? selectionOpacity.value
      : 0
  );
}

/** Sign of the change in `trendKey` across the selection (UI thread). */
function useTrendUp(trendKey: string | undefined): SharedValue<boolean> {
  const { data, selectionStartIndex, selectionEndIndex } = useChart();
  const values = useMemo(
    () => (trendKey ? data.map((d) => getNumber(d, trendKey)) : []),
    [data, trendKey]
  );
  return useDerivedValue(() => {
    const start = values[selectionStartIndex.value] ?? 0;
    const end = values[selectionEndIndex.value] ?? 0;
    return end >= start;
  });
}

export interface SegmentBackgroundProps {
  /** Fixed fill. Overrides the trend tint. */
  fill?: string;
  /** Tint green (up) / red (down) by the change in this key. */
  trendKey?: string;
  /** Trend tint strength. Default: 0.14 (matches homepage). */
  trendOpacity?: number;
}

export function SegmentBackground({
  fill,
  trendKey,
  trendOpacity = 0.14,
}: SegmentBackgroundProps) {
  const { height, margin, theme, selectionStartX, selectionEndX } = useChart();
  const opacity = useSelectionOpacity();
  const up = useTrendUp(trendKey);
  const upColor = withAlpha(theme.positive, trendOpacity);
  const downColor = withAlpha(theme.negative, trendOpacity);
  const color = useDerivedValue(() => {
    if (fill) {
      return fill;
    }
    if (!trendKey) {
      return theme.segmentBackground;
    }
    return up.value ? upColor : downColor;
  });
  const x = useDerivedValue(() => selectionStartX.value);
  const w = useDerivedValue(() => selectionEndX.value - selectionStartX.value);

  return (
    <Rect
      color={color}
      height={height - margin.top - margin.bottom}
      opacity={opacity}
      width={w}
      x={x}
      y={margin.top}
    />
  );
}

export type SegmentLineVariant = "dashed" | "solid" | "gradient";

export interface SegmentLineProps {
  /** Fixed stroke. Overrides the trend tint. */
  stroke?: string;
  /** Tint green (up) / red (down) by the change in this key. */
  trendKey?: string;
  strokeWidth?: number;
  /** Default: "dashed" (matches web). */
  variant?: SegmentLineVariant;
}

function SegmentLine({
  edge,
  stroke,
  trendKey,
  strokeWidth = 1,
  variant = "dashed",
}: SegmentLineProps & { edge: "from" | "to" }) {
  const { height, margin, theme, selectionStartX, selectionEndX } = useChart();
  const opacity = useSelectionOpacity();
  const up = useTrendUp(trendKey);
  const top = margin.top;
  const bottom = height - margin.bottom;
  const x = useDerivedValue(() =>
    edge === "from" ? selectionStartX.value : selectionEndX.value
  );
  const p1 = useDerivedValue(() => ({ x: x.value, y: top }));
  const p2 = useDerivedValue(() => ({ x: x.value, y: bottom }));
  const { positive, negative, segmentLine } = theme;
  const color = useDerivedValue(() => {
    if (stroke) {
      return stroke;
    }
    if (!trendKey) {
      return segmentLine;
    }
    return up.value ? positive : negative;
  });

  if (variant === "gradient") {
    // Gradient colour can't be animated per-trend cheaply; use the static stroke.
    const c = stroke ?? segmentLine;
    return (
      <Line opacity={opacity} p1={p1} p2={p2} strokeWidth={strokeWidth}>
        <LinearGradient
          colors={[withAlpha(c, 0), c, c, withAlpha(c, 0)]}
          end={vec(0, bottom)}
          positions={[0, 0.1, 0.9, 1]}
          start={vec(0, top)}
        />
      </Line>
    );
  }

  return (
    <Line
      color={color}
      opacity={opacity}
      p1={p1}
      p2={p2}
      strokeWidth={strokeWidth}
    >
      {variant === "dashed" ? <DashPathEffect intervals={[4, 4]} /> : null}
    </Line>
  );
}

export function SegmentLineFrom(props: SegmentLineProps) {
  return <SegmentLine {...props} edge="from" />;
}

export function SegmentLineTo(props: SegmentLineProps) {
  return <SegmentLine {...props} edge="to" />;
}

export interface SegmentChangeBadgeProps {
  /** Series whose % change across the selection is shown. */
  valueKey: string;
}

const BADGE_H = 20;
const BADGE_PAD_X = 7;
const BADGE_CHARS = "0123456789.,%+-";

/** % change across the selection, pinned above it (homepage badge). */
export function SegmentChangeBadge({ valueKey }: SegmentChangeBadgeProps) {
  const {
    data,
    width,
    fonts,
    theme,
    selectionStartX,
    selectionEndX,
    selectionStartIndex,
    selectionEndIndex,
  } = useChart();
  const opacity = useSelectionOpacity();

  const values = useMemo(
    () => data.map((d) => getNumber(d, valueKey)),
    [data, valueKey]
  );
  // Per-glyph widths so the worklet can measure labels without Skia calls.
  const charWidths = useMemo(() => {
    const widths: Record<string, number> = {};
    for (const ch of BADGE_CHARS) {
      widths[ch] = fonts.badge.getTextWidth(ch);
    }
    return widths;
  }, [fonts.badge]);

  const change = useDerivedValue(() => {
    const start = values[selectionStartIndex.value] ?? 0;
    const end = values[selectionEndIndex.value] ?? 0;
    return start === 0 ? 0 : (end - start) / start;
  });

  const label = useDerivedValue(() => {
    const pct = change.value * 100;
    const sign = pct >= 0 ? "+" : "-";
    return `${sign}${Math.abs(pct).toFixed(1)}%`;
  });

  const textWidth = useDerivedValue(() => {
    let w = 0;
    for (const ch of label.value) {
      w += charWidths[ch] ?? 0;
    }
    return w;
  });

  const badgeWidth = useDerivedValue(() => textWidth.value + BADGE_PAD_X * 2);
  const transform = useDerivedValue(() => {
    const center = (selectionStartX.value + selectionEndX.value) / 2;
    const w = badgeWidth.value;
    const x = Math.min(Math.max(center - w / 2, 0), width - w);
    return [{ translateX: x }, { translateY: 0 }];
  });

  const { positive, negative } = theme;
  const color = useDerivedValue(() =>
    change.value >= 0 ? positive : negative
  );

  return (
    <Group opacity={opacity} transform={transform}>
      <RoundedRect
        color={color}
        height={BADGE_H}
        r={4}
        width={badgeWidth}
        x={0}
        y={0}
      />
      <Text
        color="#ffffff"
        font={fonts.badge}
        text={label}
        x={BADGE_PAD_X}
        y={BADGE_H / 2 + 4}
      />
    </Group>
  );
}

/**
 * Keyed series morph geometry (pure, no Skia), so a range change zooms
 * instead of popping.
 *
 * Points are keyed by time. The morph runs over the union of old and new
 * keys:
 * - kept keys move from their old pixel position to their new one;
 * - added keys start where the OLD scales would have put them (off the edge
 *   when zooming out) and slide in;
 * - removed keys slide to where the NEW scales put them (off the edge when
 *   zooming in) instead of vanishing.
 *
 * At rest the series is drawn from the new points only.
 */

export interface KeyedPoint {
  /** Time (ms). */
  key: number;
  x: number;
  y: number;
  /** Second y: area baseline or band upper edge. */
  y0?: number;
  /** Raw value(s), so a point can be re-projected with other scales. */
  v: number;
  v0?: number;
}

/** Re-project a point with one set of scales. */
export type Projector = (p: KeyedPoint) => KeyedPoint;

export interface SeriesPoints {
  points: KeyedPoint[];
  project: Projector;
}

export function unionMorph(
  prev: SeriesPoints,
  next: SeriesPoints
): { from: KeyedPoint[]; to: KeyedPoint[] } {
  const prevBy = new Map(prev.points.map((p) => [p.key, p]));
  const nextBy = new Map(next.points.map((p) => [p.key, p]));
  const keys = [...new Set([...prevBy.keys(), ...nextBy.keys()])].sort(
    (a, b) => a - b
  );
  const from: KeyedPoint[] = [];
  const to: KeyedPoint[] = [];
  for (const key of keys) {
    const old = prevBy.get(key);
    const now = nextBy.get(key);
    if (old && now) {
      from.push(old);
      to.push(now);
    } else if (now) {
      from.push(prev.project(now));
      to.push(now);
    } else if (old) {
      from.push(old);
      to.push(next.project(old));
    }
  }
  return { from, to };
}

import {
  Group,
  LinearGradient,
  Mask,
  Rect,
  rect,
  Skia,
  type SkPath,
  vec,
} from "@shopify/react-native-skia";
import { type CurveFactory, area as d3Area, line as d3Line } from "d3-shape";
import { type ReactNode, useEffect, useMemo, useRef, useState } from "react";
import {
  type SharedValue,
  useDerivedValue,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import { getDate, getValue, useChart } from "./chart-context";
import { CHART_EASING } from "./motion";
import { type KeyedPoint, type SeriesPoints, unionMorph } from "./series-morph";

/** `true` = both sides at 15% (web default), or per-side % of plot width. */
export type FadeEdges =
  | boolean
  | "left"
  | "right"
  | { left?: number; right?: number };

const DEFAULT_FADE = 15;
/** Room past the plot edge for round caps and markers. */
const PLOT_CLIP_PAD = 6;

export function resolveFade(fade: FadeEdges): { left: number; right: number } {
  if (fade === false) {
    return { left: 0, right: 0 };
  }
  if (fade === "left") {
    return { left: DEFAULT_FADE, right: 0 };
  }
  if (fade === "right") {
    return { left: 0, right: DEFAULT_FADE };
  }
  if (typeof fade === "object") {
    const clamp = (v = 0) => Math.min(50, Math.max(0, v));
    return { left: clamp(fade.left), right: clamp(fade.right) };
  }
  return { left: DEFAULT_FADE, right: DEFAULT_FADE };
}

export function toSkPath(d: string | null): SkPath {
  return (d ? Skia.Path.MakeFromSVGString(d) : null) ?? Skia.Path.Make();
}

/**
 * Morph from the previous geometry to `target` on the UI thread whenever it
 * changes (data, scales, size). Falls back to a cut when point counts differ.
 */
export function useMorphPath(
  target: SkPath,
  duration: number
): SharedValue<SkPath> {
  const { reducedMotion } = useChart();
  const [pair, setPair] = useState({ from: target, to: target });
  const progress = useSharedValue(1);

  useEffect(() => {
    setPair((prev) =>
      prev.to === target ? prev : { from: prev.to, to: target }
    );
    if (reducedMotion) {
      progress.value = 1;
      return;
    }
    progress.value = 0;
    progress.value = withTiming(1, { duration, easing: CHART_EASING });
  }, [target, reducedMotion, duration, progress]);

  return useDerivedValue(() => {
    const { from, to } = pair;
    if (progress.value >= 1 || from === to || !to.isInterpolatable(from)) {
      return to;
    }
    return to.interpolate(from, progress.value) ?? to;
  });
}

/**
 * Morph a series whenever its points change — data, size, or a range switch
 * that adds or removes points. See `unionMorph`: the morph runs over old ∪
 * new keys so nothing pops, then the series rests on the new points.
 *
 * `series` must be memoised (see `useSeriesPoints`); `build` per curve.
 */
export function useKeyedMorph(
  series: SeriesPoints,
  build: (pts: KeyedPoint[]) => SkPath,
  duration: number
): SharedValue<SkPath> {
  const { reducedMotion } = useChart();
  const progress = useSharedValue(1);
  /** Generation whose morph has started on the UI thread. */
  const started = useSharedValue(0);
  const prevRef = useRef<SeriesPoints | null>(null);
  const pairRef = useRef<MorphPair | null>(null);

  // Built during render (refs only, no shared-value writes); the effect
  // below starts the morph. Until it does, the derived value keeps showing
  // `from` (the old geometry), so there's no flash.
  const pair = useMemo<MorphPair>(() => {
    const prev = prevRef.current;
    const current = pairRef.current;
    if (prev === series && current) {
      return current;
    }
    prevRef.current = series;
    const gen = (current?.gen ?? 0) + 1;
    const rest = build(series.points);
    let next: MorphPair = { from: rest, to: rest, rest, gen };
    if (prev && prev.points.length > 0 && !reducedMotion) {
      const union = unionMorph(prev, series);
      const from = build(union.from);
      const to = build(union.to);
      if (to.isInterpolatable(from)) {
        next = { from, to, rest, gen };
      }
    }
    pairRef.current = next;
    return next;
  }, [series, build, reducedMotion]);

  useEffect(() => {
    if (pair.from === pair.to) {
      started.value = pair.gen;
      progress.value = 1;
      return;
    }
    progress.value = 0;
    started.value = pair.gen;
    progress.value = withTiming(1, { duration, easing: CHART_EASING });
  }, [pair, duration, progress, started]);

  return useDerivedValue(() => {
    const { from, to, rest, gen } = pair;
    if (from === to) {
      return rest;
    }
    if (started.value !== gen) {
      return from;
    }
    if (progress.value >= 1) {
      return rest;
    }
    return to.interpolate(from, progress.value) ?? rest;
  });
}

interface MorphPair {
  from: SkPath;
  to: SkPath;
  /** New points only, drawn at rest. */
  rest: SkPath;
  gen: number;
}

/**
 * Pixel points for `yKey` (rows where it's defined), keyed by time, plus a
 * projector for these scales. `y0` is a second key (band upper edge) or a
 * fixed pixel baseline (area).
 */
export function useSeriesPoints(
  yKey: string,
  y0?: string | number
): SeriesPoints {
  const { data, xDataKey, xScale, yScale } = useChart();
  return useMemo(() => {
    const project = (p: KeyedPoint): KeyedPoint => ({
      ...p,
      x: xScale(new Date(p.key)),
      y: yScale(p.v),
      y0: baselineY(y0, p.v0, yScale),
    });
    const points: KeyedPoint[] = [];
    for (const d of data) {
      const v = getValue(d, yKey);
      const v0 = typeof y0 === "string" ? getValue(d, y0) : null;
      if (v === null || (typeof y0 === "string" && v0 === null)) {
        continue;
      }
      points.push(
        project({
          key: getDate(d, xDataKey).getTime(),
          x: 0,
          y: 0,
          v,
          v0: v0 ?? undefined,
        })
      );
    }
    return { points, project };
  }, [data, xDataKey, xScale, yScale, yKey, y0]);
}

function baselineY(
  y0: string | number | undefined,
  v0: number | undefined,
  yScale: (v: number) => number
): number | undefined {
  if (typeof y0 === "number") {
    return y0;
  }
  return v0 === undefined ? undefined : yScale(v0);
}

/** Line through `y` (or `y0`) of keyed points. Memoise per curve. */
export function lineBuilder(curve: CurveFactory, field: "y" | "y0" = "y") {
  return (pts: KeyedPoint[]) =>
    toSkPath(
      d3Line<KeyedPoint>()
        .x((p) => p.x)
        .y((p) => (field === "y" ? p.y : (p.y0 ?? p.y)))
        .curve(curve)(pts)
    );
}

/** Area between `y` and `y0` of keyed points. Memoise per curve. */
export function areaBuilder(curve: CurveFactory) {
  return (pts: KeyedPoint[]) =>
    toSkPath(
      d3Area<KeyedPoint>()
        .x((p) => p.x)
        .y0((p) => p.y0 ?? p.y)
        .y1((p) => p.y)
        .curve(curve)(pts)
    );
}

/**
 * Wraps a series: left-to-right reveal clip, then the horizontal edge fade
 * as an alpha mask so fill and stroke fade together.
 */
export function SeriesLayer({
  fadeEdges,
  children,
}: {
  fadeEdges: FadeEdges;
  children: ReactNode;
}) {
  const { width, height, margin, revealProgress } = useChart();
  const { left, right } = resolveFade(fadeEdges);
  const plotLeft = margin.left;
  const plotRight = width - margin.right;

  // Left-to-right reveal, and keep the series inside the plot so points
  // sliding off during a range morph never draw in the margins.
  const reveal = useDerivedValue(() => {
    const left = plotLeft - PLOT_CLIP_PAD;
    const right = Math.min(
      plotLeft + revealProgress.value * (width - plotLeft),
      plotRight + PLOT_CLIP_PAD
    );
    return rect(left, 0, Math.max(0, right - left), height);
  });

  const content = <Group clip={reveal}>{children}</Group>;
  if (left === 0 && right === 0) {
    return content;
  }

  const l = left / 100;
  const r = 1 - right / 100;
  return (
    <Mask
      mask={
        <Rect height={height} width={width} x={0} y={0}>
          <LinearGradient
            colors={[
              left > 0 ? "rgba(0,0,0,0)" : "#000",
              "#000",
              "#000",
              right > 0 ? "rgba(0,0,0,0)" : "#000",
            ]}
            end={vec(plotRight, 0)}
            positions={[0, l, r, 1]}
            start={vec(plotLeft, 0)}
          />
        </Rect>
      }
    >
      {content}
    </Mask>
  );
}

/** Web default: the rest of the series drops to 30% while scrubbing. */
export const HIGHLIGHT_DIM_OPACITY = 0.3;

/** Series opacity: dims while the tooltip is up (when highlight is on). */
export function useDimOpacity(enabled: boolean) {
  const { highlightOpacity } = useChart();
  return useDerivedValue(() =>
    enabled ? 1 - highlightOpacity.value * (1 - HIGHLIGHT_DIM_OPACITY) : 1
  );
}

/**
 * Re-draws `children` at full strength inside the springing hover band
 * (±1 point around the active index).
 */
export function HighlightBand({ children }: { children: ReactNode }) {
  const { height, highlightX, highlightWidth, highlightOpacity } = useChart();
  const band = useDerivedValue(() =>
    rect(highlightX.value, 0, Math.max(0, highlightWidth.value), height)
  );
  return (
    <Group clip={band} opacity={highlightOpacity}>
      {children}
    </Group>
  );
}

import { Circle, Group } from "@shopify/react-native-skia";
import { useEffect, useMemo } from "react";
import {
  Easing,
  useDerivedValue,
  useSharedValue,
  withDelay,
  withTiming,
} from "react-native-reanimated";
import { getDate, getValue, useChart } from "./chart-context";

export interface LineSeriesTerminalMarkerProps {
  dataKey: string;
  /** Default: theme primary. */
  stroke?: string;
  /** Dot fill. Default: `stroke`. `"transparent"` for ring only. */
  fill?: string;
  /** Gap between point and ring. Default: 6 (recipe). */
  ringGap?: number;
  size?: number;
}

const ENTER_EASING = Easing.bezier(0.22, 1, 0.36, 1);

/** Dot and ring at the series' last point (web `LineSeriesTerminalMarker`). */
export function LineSeriesTerminalMarker({
  dataKey,
  stroke,
  fill,
  ringGap = 6,
  size = 5,
}: LineSeriesTerminalMarkerProps) {
  const {
    data,
    xDataKey,
    xScale,
    yScale,
    theme,
    animationDuration,
    reducedMotion,
  } = useChart();
  const color = stroke ?? theme.linePrimary;
  const point = useMemo(() => {
    for (let i = data.length - 1; i >= 0; i--) {
      const d = data[i] ?? {};
      const v = getValue(d, dataKey);
      if (v !== null) {
        return { x: xScale(getDate(d, xDataKey)), y: yScale(v) };
      }
    }
    return null;
  }, [data, dataKey, xDataKey, xScale, yScale]);

  // Fades and scales in (0.55 → 1, 280ms) once the line has drawn.
  const progress = useSharedValue(reducedMotion ? 1 : 0);
  useEffect(() => {
    if (!reducedMotion) {
      progress.value = withDelay(
        animationDuration,
        withTiming(1, { duration: 280, easing: ENTER_EASING })
      );
    }
  }, [progress, reducedMotion, animationDuration]);
  const transform = useDerivedValue(() => [
    { scale: 0.55 + 0.45 * progress.value },
  ]);

  if (!point) {
    return null;
  }
  return (
    <Group
      opacity={progress}
      origin={{ x: point.x, y: point.y }}
      transform={transform}
    >
      <Circle color={fill ?? color} cx={point.x} cy={point.y} r={size} />
      <Circle
        color={color}
        cx={point.x}
        cy={point.y}
        r={size + ringGap + 0.75}
        strokeWidth={1.5}
        style="stroke"
      />
    </Group>
  );
}

