export interface TimeSeriesChartProps {
  data: Record<string, unknown>[];
  xDataKey?: string;
  margin?: Partial<Margin>;
  /** Width ÷ height. Ignored when `height` is set. Default: 2 (web "2 / 1"). */
  aspectRatio?: number;
  height?: number;
  /** Reveal duration in ms. Default: 1100 (matches web). */
  animationDuration?: number;
  /** Override resolved light/dark tokens. */
  theme?: Partial<ChartTheme>;
  /** Override tooltip / panel / highlight / ticker springs. */
  springs?: Partial<ChartSprings>;
  /** JS-thread callback when the scrubbed index changes; `null` on release. */
  onActiveIndexChange?: (index: number | null) => void;
  /** Override the x domain (e.g. to leave room for a forecast). */
  xDomain?: [Date, Date];
  /** JS-thread callback when a two-finger selection settles on new indices. */
  onSelectionChange?: (range: { start: number; end: number } | null) => void;
  style?: StyleProp<ViewStyle>;
  children: ReactNode;
}

// Bottom 40 (web) leaves room for the 32px date pill centred under the plot.
const DEFAULT_MARGIN: Margin = { top: 16, right: 16, bottom: 40, left: 16 };
/** Gap between crosshair and floating panel (web tooltip-box offset). */
export const TOOLTIP_OFFSET = 16;

const fontFamily = Platform.select({
  ios: "Helvetica Neue",
  default: "sans-serif",
});

interface ChartLayoutInputs {
  series: ChartSeries[];
  yValues: number[];
  xValues: Date[];
}

/** Walk children (and fragments/groups) asking each plugin for its inputs. */
function collectInputs(
  children: ReactNode,
  data: Record<string, unknown>[],
  theme: ChartTheme
): ChartLayoutInputs {
  const out: ChartLayoutInputs = { series: [], yValues: [], xValues: [] };
  const visit = (node: ReactNode) => {
    Children.forEach(node, (child) => {
      if (!isValidElement(child)) {
        return;
      }
      const plugin = getChartPlugin(child.type);
      const props = child.props as Record<string, unknown>;
      if (plugin) {
        const s = plugin.series?.(props, out.series.length, theme);
        if (s) {
          out.series.push(s);
        }
        out.yValues.push(...(plugin.yValues?.(props, data) ?? []));
        out.xValues.push(...(plugin.xValues?.(props, data) ?? []));
        return;
      }
      const nested = props.children as ReactNode;
      if (nested) {
        visit(nested);
      }
    });
  };
  visit(children);
  return out;
}

function useScales({
  data,
  xDataKey,
  inputs,
  xDomain,
  margin,
  width,
  height,
}: {
  data: Record<string, unknown>[];
  xDataKey: string;
  inputs: ChartLayoutInputs;
  xDomain?: [Date, Date];
  margin: Margin;
  width: number;
  height: number;
}) {
  const xScale = useMemo(() => {
    const dates = [...data.map((d) => getDate(d, xDataKey)), ...inputs.xValues];
    const [min = new Date(), maxDate = new Date()] = xDomain ?? extent(dates);
    return scaleTime()
      .domain([min, maxDate])
      .range([margin.left, Math.max(margin.left, width - margin.right)]);
  }, [data, xDataKey, inputs, xDomain, margin, width]);

  const yScale = useMemo(() => {
    const values = inputs.yValues;
    const lo = Math.min(0, min(values) ?? 0);
    const hi = Math.max(0, max(values) ?? 1);
    return scaleLinear()
      .domain([lo, hi === lo ? lo + 1 : hi])
      .nice()
      .range([Math.max(margin.top, height - margin.bottom), margin.top]);
  }, [inputs, margin, height]);

  const xs = useMemo(
    () => data.map((d) => xScale(getDate(d, xDataKey))),
    [data, xScale, xDataKey]
  );

  return { xScale, yScale, xs };
}

export function TimeSeriesChart({
  data,
  xDataKey = "date",
  margin: marginProp,
  aspectRatio = 2,
  height: heightProp,
  animationDuration = 1100,
  theme: themeOverride,
  springs: springsOverride,
  xDomain,
  onActiveIndexChange,
  onSelectionChange,
  style,
  children,
}: TimeSeriesChartProps) {
  const scheme = useColorScheme();
  const reducedMotion = useReducedMotion();
  const [width, setWidth] = useState(0);
  const height = heightProp ?? (width > 0 ? width / aspectRatio : 0);

  const theme = useMemo(
    () => ({
      ...(scheme === "dark" ? darkChartTheme : lightChartTheme),
      ...themeOverride,
    }),
    [scheme, themeOverride]
  );
  const springs = useMemo(() => {
    const merged = { ...DEFAULT_CHART_SPRINGS, ...springsOverride };
    return {
      tooltip: toSpring(merged.tooltip),
      tooltipBox: toSpring(merged.tooltipBox),
      highlight: toSpring(merged.highlight),
      ticker: toSpring(merged.ticker),
    };
  }, [springsOverride]);
  const margin = useMemo(
    () => ({ ...DEFAULT_MARGIN, ...marginProp }),
    [marginProp]
  );

  const fonts = useMemo<ChartFonts>(
    () => ({
      axis: matchFont({ fontFamily, fontSize: 11, fontWeight: "500" }),
      tooltip: matchFont({ fontFamily, fontSize: 13, fontWeight: "400" }),
      tooltipStrong: matchFont({ fontFamily, fontSize: 13, fontWeight: "600" }),
      ticker: matchFont({ fontFamily, fontSize: 14, fontWeight: "500" }),
      badge: matchFont({ fontFamily, fontSize: 11, fontWeight: "700" }),
    }),
    []
  );

  const inputs = useMemo(
    () => collectInputs(children, data, theme),
    [children, data, theme]
  );
  const series = inputs.series;

  const { xScale, yScale, xs } = useScales({
    data,
    xDataKey,
    inputs,
    xDomain,
    margin,
    width,
    height,
  });

  const revealProgress = useSharedValue(reducedMotion ? 1 : 0);
  const activeIndex = useSharedValue(0);
  const crosshairX = useSharedValue(0);
  const tooltipOpacity = useSharedValue(0);
  const boxX = useSharedValue(0);
  const boxWidth = useSharedValue(0);
  const tickerWidth = useSharedValue(0);
  const highlightX = useSharedValue(0);
  const highlightWidth = useSharedValue(0);
  const selectionStartX = useSharedValue(0);
  const selectionEndX = useSharedValue(0);
  const selectionStartIndex = useSharedValue(0);
  const selectionEndIndex = useSharedValue(0);
  const selectionOpacity = useSharedValue(0);
  const panelOpacity = useSharedValue(0);
  const panelEntrance = useSharedValue(1);
  const panelFlipped = useSharedValue(0);
  const dotEntrance = useSharedValue(1);
  const highlightOpacity = useSharedValue(0);

  // Worklets read layout through shared values so the gesture config can stay
  // stable across renders.
  const xsShared = useSharedValue(xs);
  const plotRight = useSharedValue(width - margin.right);
  const plotLeft = useSharedValue(margin.left);
  useEffect(() => {
    xsShared.value = xs;
    plotRight.value = width - margin.right;
    plotLeft.value = margin.left;
  }, [xs, width, margin, xsShared, plotRight, plotLeft]);

  const hasRevealed = useRef(false);
  useEffect(() => {
    if (width === 0 || hasRevealed.current) {
      return;
    }
    hasRevealed.current = true;
    revealProgress.value = reducedMotion
      ? 1
      : withTiming(1, { duration: animationDuration, easing: CHART_EASING });
  }, [width, reducedMotion, animationDuration, revealProgress]);

  const onIndexRef = useRef(onActiveIndexChange);
  onIndexRef.current = onActiveIndexChange;
  const notifyIndex = useCallback((index: number | null) => {
    onIndexRef.current?.(index);
  }, []);
  const onSelectionRef = useRef(onSelectionChange);
  onSelectionRef.current = onSelectionChange;
  const notifySelection = useCallback((start: number, end: number) => {
    onSelectionRef.current?.(start < 0 ? null : { start, end });
  }, []);

  const instant = reducedMotion;
  const tooltipSpring = springs.tooltip;
  const boxSpring = springs.tooltipBox;
  const highlightSpring = springs.highlight;

  const moveTo = (x: number, jump: boolean) => {
    "worklet";
    const arr = xsShared.value;
    const n = arr.length;
    if (n === 0) {
      return;
    }
    const i = nearestIndex(arr, x);
    const changed = i !== activeIndex.value;
    if (!(jump || changed)) {
      return;
    }
    activeIndex.value = i;
    const cx = arr[i] ?? 0;
    const w = boxWidth.value;
    const flip = cx + TOOLTIP_OFFSET + w > plotRight.value;
    const bx = flip ? cx - TOOLTIP_OFFSET - w : cx + TOOLTIP_OFFSET;
    const hx = arr[Math.max(0, i - 1)] ?? cx;
    const hw = (arr[Math.min(n - 1, i + 1)] ?? cx) - hx;
    if (!(jump || instant) && flip !== (panelFlipped.value === 1)) {
      // Web remounts the panel on flip, replaying its entrance.
      panelEntrance.value = 0;
      panelEntrance.value = withSpring(1, PANEL_ENTRANCE_SPRING);
    }
    panelFlipped.value = flip ? 1 : 0;
    if (jump || instant) {
      crosshairX.value = cx;
      boxX.value = bx;
      highlightX.value = hx;
      highlightWidth.value = hw;
    } else {
      crosshairX.value = withSpring(cx, tooltipSpring);
      boxX.value = withSpring(bx, boxSpring);
      highlightX.value = withSpring(hx, highlightSpring);
      highlightWidth.value = withSpring(hw, highlightSpring);
    }
    scheduleOnRN(notifyIndex, i);
  };

  const ms = (duration: number) => {
    "worklet";
    return instant ? 0 : duration;
  };

  // Web: crosshair, dots and ticker mount/unmount instantly; the panel fades
  // (100ms) and springs in; the series dim eases over 400ms.
  const show = () => {
    "worklet";
    tooltipOpacity.value = 1;
    panelOpacity.value = withTiming(1, { duration: ms(PANEL_FADE_MS) });
    highlightOpacity.value = withTiming(1, {
      duration: ms(HOVER_DIM_MS),
      easing: EASE_IN_OUT,
    });
    if (!instant) {
      panelEntrance.value = 0;
      panelEntrance.value = withSpring(1, PANEL_ENTRANCE_SPRING);
      dotEntrance.value = 0;
      dotEntrance.value = withSpring(1, DOT_SPRING);
    }
  };

  const hide = () => {
    "worklet";
    tooltipOpacity.value = 0;
    panelOpacity.value = withTiming(0, { duration: ms(PANEL_FADE_MS) });
    highlightOpacity.value = withTiming(0, {
      duration: ms(HOVER_DIM_MS),
      easing: EASE_IN_OUT,
    });
  };

  const scrub = usePanGesture({
    // One finger scrubs horizontally; vertical drags fall through to scroll.
    maxPointers: 1,
    activeOffsetX: [-6, 6],
    failOffsetY: [-12, 12],
    onBegin: (e) => {
      "worklet";
      selectionOpacity.value = withTiming(0, { duration: ms(SEGMENT_FADE_MS) });
      const hidden = tooltipOpacity.value === 0;
      moveTo(e.x, hidden);
      if (hidden) {
        show();
      }
    },
    onUpdate: (e) => {
      "worklet";
      moveTo(e.x, false);
    },
    onFinalize: () => {
      "worklet";
      hide();
      scheduleOnRN(notifyIndex, null);
    },
  });

  const updateSelection = (e: GestureTouchEvent) => {
    "worklet";
    const a = e.allTouches[0];
    const b = e.allTouches[1];
    const arr = xsShared.value;
    if (!(a && b) || arr.length < 2) {
      return;
    }
    const lo = Math.max(plotLeft.value, Math.min(a.x, b.x));
    const hi = Math.min(plotRight.value, Math.max(a.x, b.x));
    const si = nearestIndex(arr, lo);
    const ei = nearestIndex(arr, hi);
    selectionStartX.value = lo;
    selectionEndX.value = hi;
    if (si !== selectionStartIndex.value || ei !== selectionEndIndex.value) {
      selectionStartIndex.value = si;
      selectionEndIndex.value = ei;
      scheduleOnRN(notifySelection, si, ei);
    }
    if (tooltipOpacity.value !== 0) {
      hide();
    }
    if (selectionOpacity.value < 1) {
      selectionOpacity.value = withTiming(1, {
        duration: ms(SEGMENT_FADE_MS),
      });
    }
  };

  // Two fingers select a segment; it stays until the next touch.
  const select = usePanGesture({
    minPointers: 2,
    onTouchesDown: (e) => {
      "worklet";
      updateSelection(e);
    },
    onTouchesMove: (e) => {
      "worklet";
      updateSelection(e);
    },
  });

  const gesture = useCompetingGestures(scrub, select);

  const onLayout = useCallback((e: LayoutChangeEvent) => {
    setWidth(Math.round(e.nativeEvent.layout.width));
  }, []);

  const ctx: ChartContextValue = {
    data,
    xDataKey,
    width,
    height,
    margin,
    xScale,
    yScale,
    series,
    xs,
    theme,
    fonts,
    springs,
    animationDuration,
    reducedMotion,
    revealProgress,
    activeIndex,
    crosshairX,
    tooltipOpacity,
    boxX,
    boxWidth,
    tickerWidth,
    highlightX,
    highlightWidth,
    selectionStartX,
    selectionEndX,
    selectionStartIndex,
    selectionEndIndex,
    selectionOpacity,
    panelOpacity,
    panelEntrance,
    panelFlipped,
    dotEntrance,
    highlightOpacity,
  };

  return (
    <View
      onLayout={onLayout}
      // Reserve the final height before the first layout (aspectRatio) so
      // a remount doesn't collapse the chart for a frame.
      style={[
        heightProp === undefined
          ? { width: "100%", aspectRatio }
          : { width: "100%", height: heightProp },
        style,
      ]}
    >
      {width > 0 && height > 0 ? (
        <GestureDetector gesture={gesture}>
          <Canvas style={{ width, height }}>
            {/* Context doesn't cross the Skia reconciler, so re-provide it. */}
            <ChartContext.Provider value={ctx}>
              {children}
            </ChartContext.Provider>
          </Canvas>
        </GestureDetector>
      ) : null}
    </View>
  );
}

import {
  DashPathEffect,
  Group,
  LinearGradient,
  Path,
  Skia,
  vec,
} from "@shopify/react-native-skia";
import { useMemo } from "react";
import { getDate, getValue, useChart } from "./chart-context";
import { useEnterOpacity } from "./fade-mask";
import { DATA_TWEEN_MS } from "./motion";
import { useMorphPath } from "./series-paint";
import { withAlpha } from "./theme";

export interface TrendLineProps {
  dataKey: string;
  /** "dashed" (default, `6,4`), "solid" or "gradient". */
  strokeStyle?: "dashed" | "solid" | "gradient";
  /** Default: theme primary. */
  stroke?: string;
  /** Gradient start / end (recipe: chart-3 → chart-1). */
  gradientStart?: string;
  gradientEnd?: string;
  strokeWidth?: number;
  strokeDasharray?: number[];
  /** Fade both ends 15% along the line. Default: false. */
  fadeEdges?: boolean;
}

/** Least-squares fit of value against time. */
export function linearFit(
  data: Record<string, unknown>[],
  xKey: string,
  yKey: string
): { slope: number; intercept: number } | null {
  let n = 0;
  let sx = 0;
  let sy = 0;
  let sxx = 0;
  let sxy = 0;
  for (const d of data) {
    const y = getValue(d, yKey);
    if (y === null) {
      continue;
    }
    const x = getDate(d, xKey).getTime();
    n++;
    sx += x;
    sy += y;
    sxx += x * x;
    sxy += x * y;
  }
  const denom = n * sxx - sx * sx;
  if (n < 2 || denom === 0) {
    return null;
  }
  const slope = (n * sxy - sx * sy) / denom;
  return { slope, intercept: (sy - slope * sx) / n };
}

/** Regression line across the data (web `TrendLine`). */
export function TrendLine({
  dataKey,
  strokeStyle = "dashed",
  stroke,
  gradientStart,
  gradientEnd,
  strokeWidth = 2,
  strokeDasharray = [6, 4],
  fadeEdges = false,
}: TrendLineProps) {
  const { data, xDataKey, xScale, yScale, theme } = useChart();
  const enter = useEnterOpacity();
  const color = stroke ?? theme.linePrimary;

  const { target, p0, p1 } = useMemo(() => {
    const fit = linearFit(data, xDataKey, dataKey);
    const dates = data.map((d) => getDate(d, xDataKey).getTime());
    const t0 = Math.min(...dates);
    const t1 = Math.max(...dates);
    const b = Skia.PathBuilder.Make();
    if (!(fit && Number.isFinite(t0))) {
      return { target: b.build(), p0: vec(0, 0), p1: vec(0, 0) };
    }
    const a = vec(xScale(new Date(t0)), yScale(fit.intercept + fit.slope * t0));
    const z = vec(xScale(new Date(t1)), yScale(fit.intercept + fit.slope * t1));
    b.moveTo(a.x, a.y);
    b.lineTo(z.x, z.y);
    return { target: b.build(), p0: a, p1: z };
  }, [data, xDataKey, dataKey, xScale, yScale]);

  const path = useMorphPath(target, DATA_TWEEN_MS);
  const start = gradientStart ?? theme.chart3;
  const end = gradientEnd ?? color;
  const gradient = strokeStyle === "gradient";
  const from = gradient ? start : color;
  const to = gradient ? end : color;
  const shaded = gradient || fadeEdges;

  return (
    <Group opacity={enter}>
      <Path
        color={color}
        path={path}
        strokeCap="round"
        strokeWidth={strokeWidth}
        style="stroke"
      >
        {strokeStyle === "dashed" ? (
          <DashPathEffect intervals={strokeDasharray} />
        ) : null}
        {shaded ? (
          <LinearGradient
            colors={
              fadeEdges
                ? [withAlpha(from, 0), from, to, withAlpha(to, 0)]
                : [from, to]
            }
            end={p1}
            positions={fadeEdges ? [0, 0.15, 0.85, 1] : [0, 1]}
            start={p0}
          />
        ) : null}
      </Path>
    </Group>
  );
}

import { Group, Rect, Skia } from "@shopify/react-native-skia";
import { useMemo } from "react";
import { getDate, useChart } from "./chart-context";
import { EdgeFade, useEnterOpacity, usePlotRect } from "./fade-mask";
import { PatternFill, type PatternPreset } from "./patterns";

export interface WeekendsProps {
  /** "pattern" (default) or a flat "solid" wash. */
  variant?: "pattern" | "solid";
  pattern?: PatternPreset;
  /** Default: theme foregroundMuted. */
  color?: string;
  /** Default: 0.45 pattern / 0.08 solid (web). */
  opacity?: number;
  /** Default: 1.5 (web patternScale). */
  scale?: number;
  /** Fade the stripes top and bottom, % of plot height. Default: 0. */
  fadeVerticalLength?: number;
}

const DAY_MS = 86_400_000;

/** Saturday 00:00 → Monday 00:00 spans across the x domain. */
function weekendSpans(start: Date, end: Date): [Date, Date][] {
  const spans: [Date, Date][] = [];
  const cursor = new Date(start);
  cursor.setHours(0, 0, 0, 0);
  // Back up to this week's Saturday so a span already in progress is kept.
  cursor.setDate(cursor.getDate() - ((cursor.getDay() + 1) % 7));
  while (cursor < end) {
    const sat = new Date(cursor);
    const mon = new Date(sat.getTime() + 2 * DAY_MS);
    mon.setHours(0, 0, 0, 0);
    if (mon > start) {
      spans.push([sat < start ? start : sat, mon > end ? end : mon]);
    }
    cursor.setDate(cursor.getDate() + 7);
  }
  return spans;
}

/** Hatched (or solid) weekend stripes (web `Weekends`). */
export function Weekends({
  variant = "pattern",
  pattern = "diagonal-up",
  color,
  opacity,
  scale = 1.5,
  fadeVerticalLength = 0,
}: WeekendsProps) {
  const { data, xDataKey, xScale, theme } = useChart();
  const rect = usePlotRect();
  const enter = useEnterOpacity();
  const tint = color ?? theme.foregroundMuted;

  const stripes = useMemo(() => {
    if (data.length === 0) {
      return [];
    }
    const [d0, d1] = xScale.domain();
    return weekendSpans(d0 ?? getDate(data[0] ?? {}, xDataKey), d1 ?? d0).map(
      ([a, b]) => {
        const x0 = xScale(a);
        return { key: a.getTime(), x: x0, width: xScale(b) - x0 };
      }
    );
  }, [data, xDataKey, xScale]);

  const clip = useMemo(() => {
    const b = Skia.PathBuilder.Make();
    for (const s of stripes) {
      b.addRect(Skia.XYWHRect(s.x, rect.y, s.width, rect.height));
    }
    return b.build();
  }, [stripes, rect.y, rect.height]);

  return (
    <Group opacity={enter}>
      <EdgeFade
        bottom={fadeVerticalLength}
        rect={rect}
        top={fadeVerticalLength}
      >
        {variant === "solid" ? (
          stripes.map((s) => (
            <Rect
              color={tint}
              height={rect.height}
              key={s.key}
              opacity={opacity ?? 0.08}
              width={s.width}
              x={s.x}
              y={rect.y}
            />
          ))
        ) : (
          <PatternFill
            clip={clip}
            color={tint}
            opacity={opacity ?? 0.45}
            preset={pattern}
            rect={rect}
            scale={scale}
          />
        )}
      </EdgeFade>
    </Group>
  );
}

/**
 * X-axis tick selection, ported verbatim from web `x-axis.tsx`
 * (`selectEvenlySpacedIndices` and helpers) so native picks the same
 * data-aligned ticks: first and last rows always, even on-screen spacing,
 * `targetCount ± 1` tried. Keep in sync until this moves to a shared core.
 */

const MAX_GAP_LAYOUTS = 400;

function binomial(n: number, k: number): number {
  if (k < 0 || k > n) {
    return 0;
  }
  let result = 1;
  for (let i = 0; i < k; i++) {
    result = (result * (n - i)) / (i + 1);
  }
  return result;
}

/** All ways to split `span` into `parts` positive integer gaps. */
function composePositiveSum(sum: number, parts: number): number[][] {
  if (parts === 1) {
    return sum >= 1 ? [[sum]] : [];
  }

  const layouts: number[][] = [];
  for (let gap = 1; gap <= sum - (parts - 1); gap++) {
    for (const tail of composePositiveSum(sum - gap, parts - 1)) {
      layouts.push([gap, ...tail]);
    }
  }
  return layouts;
}

function gapsToIndices(gaps: number[]): number[] {
  const indices = [0];
  let position = 0;
  for (const gap of gaps) {
    position += gap;
    indices.push(position);
  }
  return indices;
}

function indicesForTickCount(length: number, tickCount: number): number[] {
  const span = length - 1;
  if (span <= 0) {
    return [0];
  }

  const rawIndices = Array.from({ length: tickCount }, (_, index) =>
    Math.round((index / (tickCount - 1)) * span)
  );

  const indices = [...new Set(rawIndices)].sort((a, b) => a - b);
  if (indices[0] !== 0) {
    indices.unshift(0);
  }
  if (indices.at(-1) !== span) {
    indices.push(span);
  }

  return [...new Set(indices)].sort((a, b) => a - b);
}

function allIndexLayouts(length: number, tickCount: number): number[][] {
  const span = length - 1;
  if (span <= 0) {
    return [[0]];
  }

  const gapCount = tickCount - 1;
  if (gapCount <= 0) {
    return [[0]];
  }

  const layoutCount = binomial(span - 1, gapCount - 1);
  if (layoutCount > MAX_GAP_LAYOUTS) {
    return [indicesForTickCount(length, tickCount)];
  }

  return composePositiveSum(span, gapCount).map(gapsToIndices);
}

function dedupeIndicesByLabel(indices: number[], labels: string[]): number[] {
  const seenLabels = new Set<string>();
  const deduped: number[] = [];

  for (const index of indices) {
    const label = labels[index];
    if (label === undefined || seenLabels.has(label)) {
      continue;
    }
    seenLabels.add(label);
    deduped.push(index);
  }

  return deduped;
}

interface TickLayoutScore {
  score: number;
  symmetryPenalty: number;
  countDistance: number;
  /** 0 = smallest gap at end, 1 = at start, 2 = in the middle */
  edgePreference: number;
}

function indexGaps(indices: number[]): number[] {
  const gaps: number[] = [];
  for (let i = 1; i < indices.length; i++) {
    const current = indices[i];
    const previous = indices[i - 1];
    if (current == null || previous == null) {
      continue;
    }
    gaps.push(current - previous);
  }
  return gaps;
}

function smallestGapEdgePreference(indices: number[]): number {
  const gaps = indexGaps(indices);
  const smallestGap = Math.min(...gaps);
  const smallestGapIndex = gaps.indexOf(smallestGap);
  if (smallestGapIndex === gaps.length - 1) {
    return 0;
  }
  if (smallestGapIndex === 0) {
    return 1;
  }
  return 2;
}

function scoreTickLayout(
  indices: number[],
  resolveXPx: (index: number) => number,
  targetCount: number
): TickLayoutScore {
  if (indices.length < 2) {
    return {
      score: Number.POSITIVE_INFINITY,
      symmetryPenalty: Number.POSITIVE_INFINITY,
      countDistance: Number.POSITIVE_INFINITY,
      edgePreference: Number.POSITIVE_INFINITY,
    };
  }

  const pixelGaps: number[] = [];
  for (let i = 1; i < indices.length; i++) {
    const current = indices[i];
    const previous = indices[i - 1];
    if (current == null || previous == null) {
      continue;
    }
    pixelGaps.push(resolveXPx(current) - resolveXPx(previous));
  }

  const minGap = Math.min(...pixelGaps);
  const maxGap = Math.max(...pixelGaps);
  const meanGap =
    pixelGaps.reduce((sum, gap) => sum + gap, 0) / pixelGaps.length;
  const spreadRatio =
    meanGap > 0 ? (maxGap - minGap) / meanGap : maxGap - minGap;
  const countDistance = Math.abs(indices.length - targetCount);

  const gaps = indexGaps(indices);
  const smallestGap = Math.min(...gaps);
  const smallestGapIndex = gaps.indexOf(smallestGap);
  const interiorPenalty =
    smallestGapIndex > 0 && smallestGapIndex < gaps.length - 1 ? 0.08 : 0;

  const symmetryPenalty =
    gaps.reduce((penalty, gap, index) => {
      return penalty + Math.abs(gap - (gaps.at(-1 - index) ?? gap));
    }, 0) / gaps.length;

  return {
    score:
      spreadRatio +
      0.1 * countDistance +
      interiorPenalty +
      symmetryPenalty * 0.02,
    symmetryPenalty,
    countDistance,
    edgePreference: smallestGapEdgePreference(indices),
  };
}

function isBetterTickLayout(
  next: TickLayoutScore,
  best: TickLayoutScore,
  nextCountDistance: number,
  bestCountDistance: number
): boolean {
  if (next.score < best.score - 1e-6) {
    return true;
  }
  if (Math.abs(next.score - best.score) > 1e-6) {
    return false;
  }
  if (nextCountDistance < bestCountDistance) {
    return true;
  }
  if (nextCountDistance > bestCountDistance) {
    return false;
  }
  if (next.symmetryPenalty < best.symmetryPenalty - 1e-6) {
    return true;
  }
  if (next.symmetryPenalty > best.symmetryPenalty + 1e-6) {
    return false;
  }
  return next.edgePreference < best.edgePreference;
}

/**
 * Picks tick indices with the most even on-screen spacing. Tries
 * `targetCount ± 1` and evaluates every gap layout when feasible.
 */
export function selectEvenlySpacedIndices(
  length: number,
  targetCount: number,
  options?: {
    labels?: string[];
    resolveXPx?: (index: number) => number;
  }
): number[] {
  if (length <= 0) {
    return [];
  }
  if (length === 1) {
    return [0];
  }
  if (length <= targetCount) {
    return Array.from({ length }, (_, index) => index);
  }

  const resolveXPx = options?.resolveXPx ?? ((index: number) => index);

  const minCount = Math.max(2, targetCount - 1);
  const maxCount = Math.min(length, targetCount + 1);

  let bestIndices = indicesForTickCount(length, targetCount);
  let bestScore = scoreTickLayout(bestIndices, resolveXPx, targetCount);
  let bestCountDistance = bestScore.countDistance;

  for (let tickCount = minCount; tickCount <= maxCount; tickCount++) {
    for (const rawIndices of allIndexLayouts(length, tickCount)) {
      const indices = options?.labels
        ? dedupeIndicesByLabel(rawIndices, options.labels)
        : rawIndices;

      if (indices.length < 2) {
        continue;
      }

      const layoutScore = scoreTickLayout(indices, resolveXPx, targetCount);
      const countDistance = Math.abs(indices.length - targetCount);

      if (
        isBetterTickLayout(
          layoutScore,
          bestScore,
          countDistance,
          bestCountDistance
        )
      ) {
        bestIndices = indices;
        bestScore = layoutScore;
        bestCountDistance = countDistance;
      }
    }
  }

  return bestIndices;
}

import { type SkFont, Text } from "@shopify/react-native-skia";
import { useEffect, useMemo } from "react";
import {
  type SharedValue,
  useAnimatedReaction,
  useDerivedValue,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import { getDate, useChart } from "./chart-context";
import {
  CHART_EASING,
  DATA_TWEEN_MS,
  EASE_IN_OUT,
  HOVER_DIM_MS,
} from "./motion";
import { selectEvenlySpacedIndices } from "./x-axis-ticks";

export interface XAxisProps {
  /** Ticks to aim for, including first and last. Default: 5 (web). */
  numTicks?: number;
  /**
   * "data" (default): labels sit on data rows so they line up with the
   * crosshair. "domain": evenly spaced across the time domain.
   */
  tickMode?: "data" | "domain";
  formatLabel?: (date: Date) => string;
  color?: string;
}

const defaultFormat = (date: Date) =>
  date.toLocaleDateString("en-US", { month: "short", day: "numeric" });

/** Labels fade back in over this many px past the date ticker (web: 20). */
const FADE_BUFFER = 20;
/** Keep edge labels this far inside the canvas. */
const EDGE_INSET = 4;

interface Tick {
  key: number;
  label: string;
  /** Centre x in px. */
  x: number;
}

function dedupe(ticks: Tick[]): Tick[] {
  const seen = new Set<string>();
  return ticks.filter((t) => {
    if (seen.has(t.label)) {
      return false;
    }
    seen.add(t.label);
    return true;
  });
}

/** Same tick rules as web XAxis (data-aligned, or domain when a forecast extends past the data). */
export function XAxis({
  numTicks = 5,
  tickMode = "data",
  formatLabel = defaultFormat,
  color,
}: XAxisProps) {
  const {
    data,
    xDataKey,
    width,
    height,
    margin,
    xScale,
    xs,
    theme,
    fonts,
    crosshairX,
    tooltipOpacity,
    tickerWidth,
  } = useChart();

  const ticks = useMemo<Tick[]>(() => {
    const [d0, d1] = xScale.domain();
    const last = data.at(-1);
    const extendsPastData =
      last !== undefined &&
      d1 !== undefined &&
      d1.getTime() > getDate(last, xDataKey).getTime();

    if (tickMode === "domain" || extendsPastData) {
      if (!(d0 && d1)) {
        return [];
      }
      const count = Math.max(2, numTicks);
      const span = d1.getTime() - d0.getTime();
      return dedupe(
        Array.from({ length: count }, (_, i) => {
          const date = new Date(d0.getTime() + (i / (count - 1)) * span);
          return {
            key: date.getTime(),
            label: formatLabel(date),
            x: xScale(date),
          };
        })
      );
    }

    const labels = data.map((d) => formatLabel(getDate(d, xDataKey)));
    const indices = selectEvenlySpacedIndices(data.length, numTicks, {
      labels,
      resolveXPx: (i) => xs[i] ?? i,
    });
    return dedupe(
      indices.map((i) => ({
        key: getDate(data[i] ?? {}, xDataKey).getTime(),
        label: labels[i] ?? "",
        x: xs[i] ?? 0,
      }))
    );
  }, [data, xDataKey, xScale, xs, numTicks, tickMode, formatLabel]);

  // Vertically centred on the date ticker pill.
  const y = height - margin.bottom / 2 + 4;

  return (
    <>
      {ticks.map((tick) => (
        <AxisLabel
          canvasWidth={width}
          center={tick.x}
          color={color ?? theme.label}
          crosshairX={crosshairX}
          font={fonts.axis}
          key={tick.key}
          text={tick.label}
          tickerWidth={tickerWidth}
          tooltipOpacity={tooltipOpacity}
          y={y}
        />
      ))}
    </>
  );
}

function AxisLabel({
  text,
  center,
  canvasWidth,
  y,
  font,
  color,
  crosshairX,
  tooltipOpacity,
  tickerWidth,
}: {
  text: string;
  center: number;
  canvasWidth: number;
  y: number;
  font: SkFont;
  color: string;
  crosshairX: SharedValue<number>;
  tooltipOpacity: SharedValue<number>;
  tickerWidth: SharedValue<number>;
}) {
  const w = Math.ceil(font.getTextWidth(text));
  // Centred on its point, nudged inside the canvas at the edges.
  const targetX = Math.min(
    Math.max(center - w / 2, EDGE_INSET),
    canvasWidth - w - EDGE_INSET
  );

  // Web: `left` tweens over the y-domain duration when ticks move.
  const x = useSharedValue(targetX);
  useEffect(() => {
    x.value = withTiming(targetX, {
      duration: DATA_TWEEN_MS,
      easing: CHART_EASING,
    });
  }, [x, targetX]);
  const mid = useDerivedValue(() => x.value + w / 2);

  // Hidden under the date ticker, fading back in just beyond it. Web eases
  // label opacity with `opacity 0.4s ease-in-out`.
  const target = useDerivedValue(() => {
    const half = tickerWidth.value / 2;
    if (half === 0 || tooltipOpacity.value === 0) {
      return 1;
    }
    const distance = Math.abs(mid.value - crosshairX.value);
    if (distance < half) {
      return 0;
    }
    if (distance < half + FADE_BUFFER) {
      return (distance - half) / FADE_BUFFER;
    }
    return 1;
  });
  const opacity = useSharedValue(1);
  useAnimatedReaction(
    () => target.value,
    (next, prev) => {
      if (prev !== null && next !== prev) {
        opacity.value = withTiming(next, {
          duration: HOVER_DIM_MS,
          easing: EASE_IN_OUT,
        });
      }
    }
  );

  return (
    <Text color={color} font={font} opacity={opacity} text={text} x={x} y={y} />
  );
}
